};

export default TaskDetailModal;

import { 
  collection, 
  addDoc, 
  updateDoc, 
  deleteDoc, 
  doc, 
  query, 
  where, 
  onSnapshot,
  getDocs,
  setDoc,
  writeBatch
} from "firebase/firestore";
import { 
  ref, 
  uploadBytes, 
  getDownloadURL, 
  deleteObject, 
  listAll 
} from "firebase/storage";
import { db, storage } from "./firebaseConfig";
import { User, Task, TaskStatus } from '../types';

// Collection Names
const USERS_COL = 'users';
const TASKS_COL = 'tasks';

// --- HELPER: Sanitize Data for Firestore ---
const sanitizePayload = (data: any) => {
  if (!data || typeof data !== 'object') return data;

  const clean = { ...data };
  Object.keys(clean).forEach(key => {
    if (clean[key] === undefined) {
      clean[key] = null;
    }
  });
  return clean;
};

// --- SESSION MANAGEMENT ---
export const getStoredSession = (): User | null => {
  try {
    const data = localStorage.getItem('biz_session');
    return data ? JSON.parse(data) : null;
  } catch (error) {
    return null;
  }
};

export const saveStoredSession = (user: User | null) => {
  if (user) {
    localStorage.setItem('biz_session', JSON.stringify(user));
  } else {
    localStorage.removeItem('biz_session');
  }
};

// --- REAL-TIME LISTENERS ---

export const subscribeToUsers = (companyId: string, callback: (users: User[]) => void) => {
  if (!db) return () => {};

  const q = query(collection(db, USERS_COL), where("companyId", "==", companyId));

  const unsubscribe = onSnapshot(q, (snapshot) => {
    const users: User[] = [];
    snapshot.forEach((doc) => {
      users.push({ ...doc.data(), id: doc.id } as User);
    });
    callback(users);
  });

  return unsubscribe;
};

export const subscribeToTasks = (companyId: string, callback: (tasks: Task[]) => void) => {
  if (!db) return () => {};

  const q = query(collection(db, TASKS_COL), where("companyId", "==", companyId));

  const unsubscribe = onSnapshot(q, (snapshot) => {
    const tasks: Task[] = [];
    snapshot.forEach((doc) => {
      tasks.push({ ...doc.data(), id: doc.id } as Task);
    });
    tasks.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
    callback(tasks);
  });

  return unsubscribe;
};

// --- STORAGE OPERATIONS (Images) ---

export const uploadTaskImage = async (file: File, taskId: string): Promise<string | null> => {
  if (!storage) {
    console.error("Storage not initialized");
    return null;
  }
  try {
    // Tạo tên file unique bằng timestamp
    // Loại bỏ ký tự đặc biệt để tránh lỗi URL
    const safeName = file.name.replace(/[^a-zA-Z0-9.]/g, '_');
    const fileName = `${Date.now()}_${safeName}`;
    const storageRef = ref(storage, `task_images/${taskId}/${fileName}`);

    // Thêm metadata content-type, điều này giúp browser và server xử lý đúng định dạng
    // và thường giúp vượt qua một số lỗi CORS mặc định.
    const metadata = {
      contentType: file.type,
    };

    const snapshot = await uploadBytes(storageRef, file, metadata);
    const url = await getDownloadURL(snapshot.ref);
    return url;
  } catch (e: any) {
    console.error("Upload image failed:", e);
    // Nếu là lỗi CORS (thường gặp trên localhost/vercel), ta cần báo người dùng biết
    if (e.code === 'storage/unauthorized' || e.message.includes('CORS')) {
      alert("Lỗi quyền truy cập (CORS/Rules). Vui lòng kiểm tra cấu hình Firebase Storage Rules (allow read, write).");
    }
    return null;
  }
};

// Xóa toàn bộ ảnh trong thư mục của 1 Task
export const deleteTaskAssets = async (taskId: string) => {
  if (!storage) return;
  const folderRef = ref(storage, `task_images/${taskId}`);
  try {
    const listResult = await listAll(folderRef);
    const deletePromises = listResult.items.map(item => deleteObject(item));
    await Promise.all(deletePromises);
    console.log(`Deleted assets for task ${taskId}`);
  } catch (e) {
    // Nếu folder không tồn tại hoặc lỗi, cứ bỏ qua
    console.log("No assets to delete or error", e);
  }
};

// --- CRUD OPERATIONS ---

export const apiRegisterCompany = async (user: User): Promise<boolean> => {
  if (!db) {
    alert("Vui lòng cấu hình Firebase trong file services/firebaseConfig.ts");
    return false;
  }
  try {
    await setDoc(doc(db, USERS_COL, user.id), sanitizePayload(user));
    return true;
  } catch (e) {
    console.error("Error adding company/user: ", e);
    return false;
  }
};

export const apiLogin = async (companyName: string, username: string, password: string): Promise<User | null> => {
  if (!db) {
    alert("Vui lòng cấu hình Firebase trong file services/firebaseConfig.ts");
    return null;
  }
  try {
    const q = query(
      collection(db, USERS_COL), 
      where("companyName", "==", companyName),
      where("username", "==", username),
      where("password", "==", password)
    );

    const querySnapshot = await getDocs(q);
    if (!querySnapshot.empty) {
      const userDoc = querySnapshot.docs[0];
      return { ...userDoc.data(), id: userDoc.id } as User;
    }
    return null;
  } catch (e) {
    console.error("Login error", e);
    return null;
  }
};

export const apiAddUser = async (user: User) => {
  if (!db) return;
  await setDoc(doc(db, USERS_COL, user.id), sanitizePayload(user));
};

export const apiUpdateUser = async (user: User) => {
  if (!db) return;
  const userRef = doc(db, USERS_COL, user.id);
  const { id, ...data } = user;
  await updateDoc(userRef, sanitizePayload(data));
};

export const apiDeleteUser = async (userId: string) => {
  if (!db) return;
  try {
      await deleteDoc(doc(db, USERS_COL, userId));
  } catch (error) {
      console.error("Error deleting user:", error);
  }
};

export const apiAddTask = async (task: Task) => {
  if (!db) return;
  await setDoc(doc(db, TASKS_COL, task.id), sanitizePayload(task));
};

export const apiUpdateTask = async (task: Task) => {
  if (!db) return;
  const taskRef = doc(db, TASKS_COL, task.id);
  await updateDoc(taskRef, sanitizePayload(task)); 
};

export const apiDeleteTask = async (taskId: string) => {
  if (!db) return;
  // 1. Xóa ảnh trên Storage trước
  await deleteTaskAssets(taskId);
  // 2. Xóa doc trong Firestore
  await deleteDoc(doc(db, TASKS_COL, taskId));
};

export const apiCheckUsernameExists = async (companyName: string, username: string): Promise<boolean> => {
  if (!db) return false;
  const q = query(
    collection(db, USERS_COL), 
    where("companyName", "==", companyName),
    where("username", "==", username)
  );
  const snapshot = await getDocs(q);
  return !snapshot.empty;
};

/**
 * Xóa các công việc đã hoàn thành quá 90 ngày
 * VÀ XÓA CẢ ẢNH LIÊN QUAN TRÊN STORAGE
 */
export const cleanupOldTasks = async (companyId: string) => {
    if (!db) return;

    try {
        const ninetyDaysAgo = new Date();
        ninetyDaysAgo.setDate(ninetyDaysAgo.getDate() - 90);

        const q = query(
            collection(db, TASKS_COL),
            where("companyId", "==", companyId),
            where("status", "==", TaskStatus.COMPLETED)
        );

        const snapshot = await getDocs(q);
        const batch = writeBatch(db);
        let count = 0;

        for (const doc of snapshot.docs) {
            const task = doc.data() as Task;
            const dateToCheck = task.completedAt ? new Date(task.completedAt) : new Date(task.createdAt);

            if (dateToCheck < ninetyDaysAgo) {
                // QUAN TRỌNG: Gọi hàm xóa ảnh
                await deleteTaskAssets(task.id);

                batch.delete(doc.ref);
                count++;
            }
        }

        if (count > 0) {
            await batch.commit();
            console.log(`Đã dọn dẹp ${count} công việc cũ và giải phóng bộ nhớ ảnh.`);
        }
    } catch (e) {
        console.error("Lỗi khi dọn dẹp dữ liệu cũ:", e);
    }
};

import React, { useState, useRef, useEffect } from 'react';
import { User, UserRole, TaskPriority, Task } from '../types';
import { analyzeTaskAudio } from '../services/geminiService';
import { uploadTaskImage } from '../services/storageService';
import { IconMic, IconX, IconImage, IconAlert } from './Icons';

interface CreateTaskModalProps {
  currentUser: User;
  assignableUsers: User[]; 
  onClose: () => void;
  onCreate: (taskData: any) => Promise<void>;
  onEdit?: (taskData: any) => Promise<void>;
  initialData?: Task;
}

const CreateTaskModal: React.FC<CreateTaskModalProps> = ({ currentUser, assignableUsers, onClose, onCreate, onEdit, initialData }) => {
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [dueDate, setDueDate] = useState('');
  const [assigneeId, setAssigneeId] = useState(currentUser.id);
  const [priority, setPriority] = useState<TaskPriority>(TaskPriority.MEDIUM);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [isUploading, setIsUploading] = useState(false);

  // Image State
  const [selectedFiles, setSelectedFiles] = useState<File[]>([]);
  const [existingImages, setExistingImages] = useState<string[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Audio Recording Refs
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  const canAssign = currentUser.role === UserRole.MANAGER;

  // Load initial data if editing
  useEffect(() => {
    if (initialData) {
      setTitle(initialData.title);
      setDescription(initialData.description);
      // Format date for input datetime-local: YYYY-MM-DDTHH:mm
      try {
        const d = new Date(initialData.dueDate);
        // Adjust to local ISO string manually to handle timezone correctly for inputs
        const localIso = new Date(d.getTime() - (d.getTimezoneOffset() * 60000)).toISOString().slice(0, 16);
        setDueDate(localIso);
      } catch (e) {
        setDueDate('');
      }

      setAssigneeId(initialData.assigneeId);
      setPriority(initialData.priority);
      if (initialData.attachments) {
        setExistingImages(initialData.attachments);
      }
    }
  }, [initialData]);

  // Voice Command Logic
  const handleVoiceCommand = async () => {
    if (isRecording) {
      if (mediaRecorderRef.current && mediaRecorderRef.current.state === "recording") {
        mediaRecorderRef.current.stop();
        setIsRecording(false);
        setIsAnalyzing(true);
      }
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        const mediaRecorder = new MediaRecorder(stream);
        mediaRecorderRef.current = mediaRecorder;
        audioChunksRef.current = [];

        mediaRecorder.ondataavailable = (event) => {
          if (event.data.size > 0) {
            audioChunksRef.current.push(event.data);
          }
        };

        mediaRecorder.onstop = async () => {
          const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
          const reader = new FileReader();
          reader.readAsDataURL(audioBlob);
          reader.onloadend = async () => {
            const base64String = reader.result as string;
            const base64Data = base64String.split(',')[1];
            const transcription = await analyzeTaskAudio(base64Data, audioBlob.type || 'audio/webm');

            if (transcription) {
              if (!title) {
                setTitle(transcription);
              } else {
                setDescription(prev => (prev ? prev + '\n' + transcription : transcription));
              }
            }
            setIsAnalyzing(false);
            stream.getTracks().forEach(track => track.stop());
          };
        };

        mediaRecorder.start();
        setIsRecording(true);
      } catch (err) {
        console.error("Error accessing microphone:", err);
        alert("Không thể truy cập Microphone. Vui lòng kiểm tra quyền truy cập.");
      }
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const filesArray = Array.from(e.target.files);
      // Validate file size (e.g., max 5MB)
      const oversizedFiles = filesArray.filter(f => f.size > 5 * 1024 * 1024);
      if (oversizedFiles.length > 0) {
        alert("Một số ảnh quá lớn (>5MB) và sẽ bị bỏ qua.");
      }
      const validFiles = filesArray.filter(f => f.size <= 5 * 1024 * 1024);
      setSelectedFiles(prev => [...prev, ...validFiles]);
    }
  };

  const removeSelectedFile = (index: number) => {
    setSelectedFiles(prev => prev.filter((_, i) => i !== index));
  };

  const removeExistingImage = (url: string) => {
    setExistingImages(prev => prev.filter(img => img !== url));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title || !dueDate) {
       alert("Vui lòng nhập tiêu đề và hạn chót!");
       return;
    }

    setIsUploading(true);

    try {
      const tempTaskId = initialData?.id || Math.random().toString(36).substr(2, 9);

      // Upload images
      const uploadPromises = selectedFiles.map(file => uploadTaskImage(file, tempTaskId));
      const results = await Promise.all(uploadPromises);

      // Filter successful uploads
      const validNewUrls = results.filter(url => url !== null) as string[];

      // Error handling for uploads
      if (selectedFiles.length > 0 && validNewUrls.length === 0) {
         const continueSave = window.confirm("Không thể tải ảnh lên (Lỗi kết nối hoặc quyền truy cập). Bạn có muốn tiếp tục lưu công việc mà không có ảnh mới?");
         if (!continueSave) {
           setIsUploading(false);
           return;
         }
      } else if (selectedFiles.length > validNewUrls.length) {
         alert(`Cảnh báo: Chỉ tải lên được ${validNewUrls.length}/${selectedFiles.length} ảnh.`);
      }

      const allAttachments = [...existingImages, ...validNewUrls];

      const data = {
        id: tempTaskId, 
        title,
        description,
        dueDate: new Date(dueDate).toISOString(),
        assigneeId: canAssign ? assigneeId : currentUser.id,
        priority,
        attachments: allAttachments
      };

      if (initialData && onEdit) {
        await onEdit({ ...initialData, ...data });
      } else {
        await onCreate(data);
      }
      onClose(); // Close strictly after success
    } catch (error) {
      console.error("Error saving task:", error);
      alert("Có lỗi xảy ra khi lưu công việc. Vui lòng thử lại.");
    } finally {
      setIsUploading(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/50 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 backdrop-blur-sm animate-fade-in">
      <div className="bg-white w-full sm:max-w-lg rounded-t-2xl sm:rounded-2xl p-6 shadow-2xl animate-slide-up sm:animate-none max-h-[90vh] overflow-y-auto custom-scrollbar flex flex-col">
        <div className="flex justify-between items-center mb-6 border-b border-gray-100 pb-4">
          <h2 className="text-xl font-bold text-navy-800">
            {initialData ? 'Sửa Công Việc' : 'Giao Việc Mới'}
          </h2>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600 p-2 rounded-full hover:bg-gray-100"><IconX className="w-5 h-5"/></button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-5">

          {/* Title Input */}
          <div>
            <label className="block text-sm font-bold text-gray-700 mb-1">Nhiệm vụ <span className="text-red-500">*</span></label>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="VD: Báo cáo thu chi tháng 12..."
              className="w-full p-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-navy-800 outline-none transition-all font-medium"
              required={!isRecording}
              disabled={isUploading}
            />
          </div>

          {/* Description Input with Voice */}
