                  required
                  disabled={isUploading}
                />
             </div>
             <div>
                <label className="block text-sm font-bold text-gray-700 mb-1">Độ ưu tiên</label>
                <select
                  value={priority}
                  onChange={(e) => setPriority(e.target.value as TaskPriority)}
