// --- Helper Functions ---
const isOverdue = (dateString: string) => {
  const due = new Date(dateString);
  const now = new Date();
  return due < now;
};

const formatDateTime = (dateString: string) => {
  const date = new Date(dateString);
  return new Intl.DateTimeFormat('vi-VN', { 
    hour: '2-digit', 
    minute: '2-digit',
    day: '2-digit', 
    month: '2-digit',
  }).format(date);
};

const getDeadlineInfo = (dueDateStr: string, status: TaskStatus) => {
  if (status === TaskStatus.COMPLETED) return null;

  const due = new Date(dueDateStr);
  const now = new Date();

  const diffTime = due.getTime() - now.getTime();
  const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

  if (diffDays < 0) {
    return { text: 'Quá hạn', className: 'bg-red-500 text-white', icon: true };
  }

  if (diffDays === 0) {
    return { text: 'Hết hạn hôm nay', className: 'bg-red-100 text-red-700 border border-red-200' };
  }

  if (diffDays <= 3) {
    return { text: `Còn ${diffDays} ngày`, className: 'bg-orange-100 text-orange-700 border border-orange-200' };
  }

  if (diffDays <= 7) {
    return { text: `Còn ${diffDays} ngày`, className: 'bg-yellow-100 text-yellow-700 border border-yellow-200' };
  }

  return { text: `Còn ${diffDays} ngày`, className: 'bg-green-100 text-green-700 border border-green-200' };
};

export default function App() {
