              <div onClick={() => { setStartDate(''); setEndDate(''); setStatusFilter(TaskStatus.TODO); setActiveTab('tasks'); }} className="bg-gradient-to-br from-yellow-50 to-orange-50 p-5 rounded-2xl shadow-sm border border-yellow-100 flex flex-col items-center justify-center gap-2 text-center aspect-[4/3] cursor-pointer hover:shadow-md hover:-translate-y-1 transition-all">
                <span className="w-12 h-12 rounded-full bg-yellow-200/50 flex items-center justify-center text-yellow-700"><IconClock className="w-6 h-6" /></span>
                <span className="text-4xl font-bold text-yellow-800">{stats.pending}</span>
                <span className="text-xs font-bold text-yellow-700 uppercase tracking-wide">Chờ xử lý</span>
              </div>
              <div onClick={() => { setStartDate(''); setEndDate(''); setStatusFilter(TaskStatus.IN_PROGRESS); setActiveTab('tasks'); }} className="bg-gradient-to-br from-blue-50 to-sky-50 p-5 rounded-2xl shadow-sm border border-blue-100 flex flex-col items-center justify-center gap-2 text-center aspect-[4/3] cursor-pointer hover:shadow-md hover:-translate-y-1 transition-all">
                <span className="w-12 h-12 rounded-full bg-blue-200/50 flex items-center justify-center text-blue-700"><IconList className="w-6 h-6" /></span>
                <span className="text-4xl font-bold text-blue-800">{stats.inProgress}</span>
                <span className="text-xs font-bold text-blue-700 uppercase tracking-wide">Đang làm</span>
              </div>
              <div onClick={() => navigateToMonthStats(TaskStatus.COMPLETED)} className="bg-gradient-to-br from-green-50 to-emerald-50 p-5 rounded-2xl shadow-sm border border-green-100 flex flex-col items-center justify-center gap-2 text-center aspect-[4/3] cursor-pointer hover:shadow-md hover:-translate-y-1 transition-all">
                <span className="w-12 h-12 rounded-full bg-green-200/50 flex items-center justify-center text-green-700"><IconCheck className="w-6 h-6" /></span>
                <span className="text-4xl font-bold text-green-800">{stats.completedMonth}</span>
                <div className="flex flex-col items-center"><span className="text-xs font-bold text-green-700 uppercase tracking-wide">Đã xong</span><span className="text-[10px] text-green-600 font-semibold">(Tháng này)</span></div>
              </div>
              <div onClick={() => navigateToMonthStats('OVERDUE')} className="bg-gradient-to-br from-red-50 to-rose-50 p-5 rounded-2xl shadow-sm border border-red-100 flex flex-col items-center justify-center gap-2 text-center aspect-[4/3] cursor-pointer hover:shadow-md hover:-translate-y-1 transition-all">
                <span className="w-12 h-12 rounded-full bg-red-200/50 flex items-center justify-center text-red-700"><IconAlert className="w-6 h-6" /></span>
                <span className="text-4xl font-bold text-red-800">{stats.overdueMonth}</span>
                <div className="flex flex-col items-center"><span className="text-xs font-bold text-red-700 uppercase tracking-wide">Trễ hạn</span><span className="text-[10px] text-red-600 font-semibold">(Tháng này)</span></div>
              </div>
            </div>

            {/* MONTH SUMMARY */}
            <div className="bg-gradient-to-br from-navy-800 to-navy-900 p-6 rounded-2xl shadow-xl text-white relative overflow-hidden group">
               <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity"><IconChart className="w-32 h-32" /></div>
               <div className="relative z-10">
                  <h3 className="text-lg font-bold mb-6 flex items-center gap-2"><IconChart className="w-5 h-5 text-blue-300"/> Tổng kết Tháng {new Date().getMonth() + 1}</h3>
                  <div className="grid grid-cols-2 gap-8">
                    <div>
                      <p className="text-blue-200 text-xs font-semibold uppercase tracking-wider mb-2">Công việc tồn đọng</p>
                      <div className="flex flex-col">
                        <span className="text-4xl font-bold text-white mb-1">{stats.pending + stats.inProgress}</span>
                        <span className="text-xs font-medium text-blue-200 opacity-80">so với <span className="text-green-400 font-bold">{stats.completedMonth}</span> đã xong</span>
                      </div>
                    </div>
                    <div className="border-l border-navy-600 pl-6">
                      <p className="text-blue-200 text-xs font-semibold uppercase tracking-wider mb-2">Tác vụ trễ hạn</p>
                      <div className="flex flex-col">
                         <div className="flex items-baseline gap-2">
                            <span className={`text-4xl font-bold ${stats.overdueMonth > 0 ? 'text-red-400' : 'text-green-400'}`}>{stats.overdueMonth}</span>
                            <span className="text-sm text-blue-200">việc</span>
                         </div>
                         <span className="text-xs font-medium text-blue-200 opacity-80">Chiếm <span className="text-white font-bold">{stats.overdueRate}%</span> tổng số</span>
                      </div>
                    </div>
                  </div>
               </div>
            </div>
          </div>
        )}

        {activeTab === 'tasks' && (
          <div className="space-y-4">
            <div className="relative">
              <input type="text" placeholder={currentUser.role === UserRole.MANAGER ? "Tìm công việc toàn công ty..." : "Tìm trong việc của tôi..."} value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} className="w-full pl-11 pr-4 py-3.5 rounded-xl border border-gray-200 shadow-sm focus:ring-2 focus:ring-navy-800 outline-none text-sm bg-white" />
              <IconSearch className="absolute left-4 top-4 w-4 h-4 text-gray-400" />
            </div>

            <div className="flex flex-col sm:flex-row gap-3 bg-white p-3 rounded-xl border border-gray-200 shadow-sm">
               <div className="flex-1">
                 <label className="text-[10px] text-gray-500 font-bold px-1 uppercase block mb-1">Từ ngày</label>
                 <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full text-xs text-gray-700 font-medium outline-none p-1 bg-gray-50 rounded" />
