          </div>
        )}

        {activeTab === 'profile' && (
           <div className="p-2 space-y-6 max-w-3xl mx-auto">
              <div className="bg-white rounded-2xl p-8 shadow-sm border border-gray-200 flex flex-col items-center relative overflow-hidden">
                 <div className="absolute top-0 left-0 w-full h-24 bg-navy-800"></div>
                 <div className="relative z-10 flex flex-col items-center w-full">
                   <img src={currentUser.avatar} className="w-28 h-28 rounded-full mb-4 object-cover border-4 border-white shadow-md" />
                   <h2 className="text-2xl font-bold text-gray-800">{currentUser.name}</h2>
                   <p className="text-sm font-medium text-gray-500 mb-6">{currentUser.companyName} • {currentUser.role === UserRole.MANAGER ? 'Quản lý' : 'Nhân viên'}</p>

                   <div className="flex gap-4 w-full max-w-md">
                      {currentUser.role === UserRole.MANAGER && (
                        <button onClick={() => setShowChangePassModal(true)} className="flex-1 py-3 bg-white border border-gray-200 text-gray-700 font-bold rounded-xl text-sm hover:bg-gray-50 hover:border-gray-300 transition-colors flex items-center justify-center gap-2 shadow-sm"><IconKey className="w-4 h-4" /> Đổi mật khẩu</button>
                      )}
                      <button onClick={handleLogout} className="flex-1 py-3 bg-red-50 text-red-600 border border-red-100 font-bold rounded-xl text-sm hover:bg-red-100 transition-colors flex items-center justify-center gap-2 shadow-sm"><IconLogOut className="w-4 h-4" /> Đăng xuất</button>
                   </div>
                 </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="bg-white rounded-2xl p-6 shadow-sm border border-gray-200">
                   <h3 className="font-bold text-gray-800 mb-4 flex items-center gap-2"><IconAlert className="w-5 h-5 text-orange-500"/> Cài đặt Thông báo</h3>
                   <div className="space-y-3">
                     <button onClick={requestNotificationAccess} className="w-full flex justify-between items-center p-4 bg-gray-50 rounded-xl hover:bg-gray-100 border border-transparent hover:border-gray-200 transition-all">
                       <div className="flex items-center gap-3"><div className={`p-2 rounded-full ${notificationPermission === 'granted' ? 'bg-green-100 text-green-600' : 'bg-orange-100 text-orange-600'}`}>{notificationPermission === 'granted' ? <IconCheck className="w-5 h-5" /> : <IconAlert className="w-5 h-5" />}</div><div className="text-left"><div className="font-bold text-sm text-gray-800">Quyền Thông báo & Badge</div><div className="text-xs text-gray-500">{notificationPermission === 'granted' ? 'Đã kích hoạt' : 'Chưa kích hoạt'}</div></div></div>
                     </button>
                     <button onClick={testBadge} className="w-full flex justify-between items-center p-4 bg-gray-50 rounded-xl hover:bg-gray-100 border border-transparent hover:border-gray-200 transition-all">
                       <div className="flex items-center gap-3"><div className="bg-blue-100 p-2 rounded-full text-blue-600"><IconCheck className="w-5 h-5" /></div><div className="text-left"><div className="font-bold text-sm text-gray-800">Kiểm tra Badge Icon</div><div className="text-xs text-gray-500">Test hiển thị số đỏ trên icon</div></div></div>
                     </button>
                   </div>
                </div>

                {currentUser.role === UserRole.MANAGER && (
                  <div className="bg-white rounded-2xl p-6 shadow-sm border border-gray-200">
                     <UserManagement currentUser={currentUser} companyUsers={users} onAddUser={handleAddUser} onDeleteUser={handleDeleteUser} />
                  </div>
                )}
              </div>
           </div>
        )}
      </main>

      {currentUser.role === UserRole.MANAGER && (
        <button onClick={() => setShowCreateModal(true)} className="fixed bottom-24 right-6 bg-navy-800 text-white w-14 h-14 rounded-full shadow-2xl flex items-center justify-center hover:scale-110 hover:bg-navy-900 transition-all z-20 border-4 border-white">
          <IconPlus className="w-7 h-7" />
        </button>
      )}

      {/* FOOTER NAV */}
      <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 px-6 py-3 flex justify-between items-center z-20 pb-safe shadow-[0_-5px_10px_rgba(0,0,0,0.02)]">
        <NavButton active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon={<IconHome />} label="Tổng quan" />
        <NavButton active={activeTab === 'tasks'} onClick={() => setActiveTab('tasks')} icon={<IconList />} label="Công việc" badge={myPendingTaskCount > 0 ? myPendingTaskCount : undefined} />
        <NavButton active={activeTab === 'team'} onClick={() => setActiveTab('team')} icon={<IconBriefcase />} label="Nhân sự" />
        <NavButton active={activeTab === 'profile'} onClick={() => setActiveTab('profile')} icon={<IconUser />} label="Cá nhân" />
      </nav>

      {/* MODALS */}
      {showCreateModal && <CreateTaskModal currentUser={currentUser} assignableUsers={users} onClose={() => setShowCreateModal(false)} onCreate={createTask} />}
      {editingTask && <CreateTaskModal currentUser={currentUser} assignableUsers={users} onClose={() => setEditingTask(null)} onCreate={async () => {}} onEdit={submitEditTask} initialData={editingTask} />}

      {/* Detail Modal */}
      {viewingTask && <TaskDetailModal task={viewingTask} users={users} onClose={() => setViewingTask(null)} onEdit={(t) => { setViewingTask(null); handleEditTask(t); }} />}

      {showCompleteModal && completingTask && (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm animate-fade-in">
           <div className="bg-white w-full max-w-sm rounded-2xl p-6 shadow-2xl transform transition-all scale-100">
              <h3 className="text-lg font-bold text-navy-800 mb-2">Xác nhận hoàn thành</h3>
              <p className="text-sm text-gray-500 mb-6">Bạn có muốn tải ảnh minh chứng (kết quả công việc) lên không?</p>
              <div className="mb-6">
                 <label className="block w-full border-2 border-dashed border-gray-300 rounded-xl p-8 text-center cursor-pointer hover:border-navy-500 hover:bg-gray-50 transition-colors group">
                    {completionFile ? (
                       <div className="relative">
                          <img src={URL.createObjectURL(completionFile)} className="h-32 mx-auto object-contain rounded shadow-sm" />
                          <button onClick={(e) => { e.preventDefault(); setCompletionFile(null); }} className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1 shadow-md hover:bg-red-600"><IconX className="w-3 h-3" /></button>
                       </div>
                    ) : (
                       <div className="flex flex-col items-center text-gray-400 group-hover:text-navy-600">
                          <IconImage className="w-10 h-10 mb-2" /><span className="text-sm font-bold">Chọn ảnh (Tùy chọn)</span>
                       </div>
                    )}
                    <input type="file" className="hidden" accept="image/*" onChange={(e) => e.target.files && setCompletionFile(e.target.files[0])} />
                 </label>
              </div>
              <div className="flex gap-3">
                <button onClick={() => setShowCompleteModal(false)} className="flex-1 py-3 bg-gray-100 text-gray-700 font-bold rounded-xl hover:bg-gray-200">Hủy</button>
                <button onClick={confirmCompleteTask} disabled={isSubmittingComplete} className="flex-1 py-3 bg-green-600 text-white font-bold rounded-xl flex justify-center items-center hover:bg-green-700 shadow-lg shadow-green-200">
                  {isSubmittingComplete ? <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div> : 'Hoàn thành'}
                </button>
              </div>
           </div>
        </div>
      )}

      {showChangePassModal && (
         <div className="fixed inset-0 bg-black/60 z-[60] flex items-center justify-center p-4 backdrop-blur-sm animate-fade-in">
            <div className="bg-white w-full max-w-sm rounded-2xl p-6 shadow-2xl">
               <h3 className="text-lg font-bold text-navy-800 mb-4">Đổi mật khẩu đăng nhập</h3>
               <p className="text-sm text-gray-500 mb-6">Nhập mật khẩu mới cho tài khoản của bạn.</p>
               <input type="text" value={newSelfPass} onChange={(e) => setNewSelfPass(e.target.value)} placeholder="Mật khẩu mới" className="w-full p-3.5 border border-gray-300 rounded-xl mb-6 focus:ring-2 focus:ring-navy-800 outline-none" />
               <div className="flex gap-3">
                  <button onClick={() => setShowChangePassModal(false)} className="flex-1 py-3 bg-gray-100 text-gray-700 font-bold rounded-xl hover:bg-gray-200">Hủy</button>
                  <button onClick={handleChangeSelfPass} disabled={!newSelfPass} className="flex-1 py-3 bg-navy-800 text-white font-bold rounded-xl hover:bg-navy-900 shadow-lg disabled:opacity-50">Lưu</button>
               </div>
            </div>
         </div>
      )}

      {lightboxImage && (
         <div className="fixed inset-0 bg-black/95 z-[70] flex items-center justify-center p-4" onClick={() => setLightboxImage(null)}>
            <img src={lightboxImage} className="max-w-full max-h-full object-contain rounded-lg shadow-2xl" />
            <button className="absolute top-6 right-6 text-white bg-white/20 hover:bg-white/40 p-2 rounded-full backdrop-blur-sm transition-colors"><IconX className="w-6 h-6" /></button>
         </div>
      )}

      {reassignTask && (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm animate-fade-in">
           <div className="bg-white w-full max-w-sm rounded-2xl p-6 shadow-2xl">
              <h3 className="text-lg font-bold text-navy-800 mb-4">Giao lại việc cho</h3>
              <div className="space-y-2 mb-6 max-h-[50vh] overflow-y-auto">
                 {users.map(user => (
                   <button key={user.id} onClick={() => handleReassign(user.id)} className="w-full flex items-center gap-3 p-3 rounded-xl hover:bg-blue-50 border border-transparent hover:border-blue-100 transition-colors">
                     <img src={user.avatar} className="w-10 h-10 rounded-full border border-gray-200" />
                     <div className="text-left"><div className="font-bold text-gray-800">{user.name}</div><div className="text-xs text-gray-500">@{user.username}</div></div>
                   </button>
                 ))}
              </div>
              <button onClick={() => setReassignTask(null)} className="w-full py-3 bg-gray-100 text-gray-700 font-bold rounded-xl hover:bg-gray-200">Hủy bỏ</button>
           </div>
        </div>
      )}
    </div>
  );
}

const NavButton = ({ active, onClick, icon, label, badge }: any) => (
  <button onClick={onClick} className={`flex flex-col items-center gap-1 transition-all relative ${active ? 'text-navy-800 font-bold scale-105' : 'text-gray-400 hover:text-gray-600'}`}>
    <div className="relative">
       {React.cloneElement(icon, { className: 'w-6 h-6', strokeWidth: active ? 2.5 : 2 })}
       {badge && <span className="absolute -top-1 -right-2 bg-red-600 text-white text-[10px] font-bold w-4 h-4 flex items-center justify-center rounded-full animate-pulse border-2 border-white shadow-sm">{badge > 9 ? '9+' : badge}</span>}
    </div>
    <span className="text-[10px] tracking-wide">{label}</span>
  </button>
);

interface TaskCardProps {
  task: Task;
  currentUser: User;
  allUsers: User[];
  onStatusAction: (task: Task) => void;
  onReassign: (task: Task) => void;
  onEdit: (task: Task) => void;
  onViewImage: (url: string) => void;
  onViewDetail: () => void; // New prop for detail view
  isDashboard?: boolean;
}

const TaskCard: React.FC<TaskCardProps> = ({ task, currentUser, allUsers, onStatusAction, onReassign, onEdit, onViewImage, onViewDetail, isDashboard }) => {
  const overdue = task.status !== TaskStatus.COMPLETED && isOverdue(task.dueDate);
  const isManager = currentUser.role === UserRole.MANAGER;
  const isAssignee = currentUser.id === task.assigneeId;
  const canEditStatus = isManager || isAssignee;
  const canEditContent = isManager;
  const showAction = isDashboard ? isAssignee : canEditStatus;

  const priorityColors = {
    [TaskPriority.LOW]: 'bg-gray-100 text-gray-600',
    [TaskPriority.MEDIUM]: 'bg-blue-50 text-blue-600',
    [TaskPriority.HIGH]: 'bg-orange-50 text-orange-600',
    [TaskPriority.URGENT]: 'bg-red-50 text-red-600',
  };

  const assignee = allUsers.find(u => u.id === task.assigneeId);
  const creator = allUsers.find(u => u.id === task.creatorId);
  const deadlineInfo = getDeadlineInfo(task.dueDate, task.status);

  return (
    <div 
      className={`bg-white p-5 rounded-2xl border ${overdue ? 'border-red-200' : 'border-gray-100'} shadow-sm hover:shadow-md transition-shadow relative overflow-hidden group h-full flex flex-col cursor-pointer`}
      onClick={onViewDetail} // Make entire card clickable
    >
      {overdue && <div className="absolute top-0 right-0 bg-red-500 text-white text-[10px] px-3 py-1 rounded-bl-xl font-bold z-10 shadow-sm">Quá hạn</div>}

      <div className="flex justify-between items-start mb-3">
        <span className={`text-[10px] px-2.5 py-1 rounded-md font-bold uppercase tracking-wider ${priorityColors[task.priority]}`}>{task.priority}</span>
        <div className="flex flex-col items-end gap-1">
          {deadlineInfo && <span className={`text-[10px] px-2.5 py-1 rounded-full font-bold flex items-center gap-1 ${deadlineInfo.className}`}>{deadlineInfo.icon && <IconAlert className="w-3 h-3" />}{deadlineInfo.text}</span>}
        </div>
      </div>

      <div className="flex justify-between items-start mb-2">
         <h3 className="font-bold text-gray-800 text-base leading-tight flex-1 group-hover:text-navy-800 transition-colors">{task.title}</h3>
         {canEditContent && (
             <button onClick={(e) => { e.stopPropagation(); onEdit(task); }} className="text-gray-300 hover:text-navy-600 p-1 transition-colors"><IconEdit className="w-4 h-4" /></button>
         )}
      </div>

      <p className="text-sm text-gray-500 line-clamp-3 mb-4 whitespace-pre-line flex-1">{task.description}</p>

      {/* Attachments Preview (Max 3) */}
      {task.attachments && task.attachments.length > 0 && (
         <div className="flex gap-2 overflow-x-auto pb-2 mb-3 hide-scrollbar" onClick={(e) => e.stopPropagation()}>
            {task.attachments.slice(0, 4).map((url, i) => (
               <img key={i} src={url} onClick={() => onViewImage(url)} className="w-12 h-12 rounded-lg object-cover flex-shrink-0 cursor-pointer border border-gray-200 hover:opacity-80 transition-opacity" />
            ))}
            {task.attachments.length > 4 && <div className="w-12 h-12 rounded-lg bg-gray-50 flex items-center justify-center text-xs text-gray-500 font-bold border border-gray-200">+{task.attachments.length - 4}</div>}
         </div>
      )}

      {/* Completion Proof */}
      {task.status === TaskStatus.COMPLETED && task.completionImage && (
         <div className="mb-4 bg-green-50 p-2.5 rounded-xl border border-green-100 flex items-center gap-3" onClick={(e) => e.stopPropagation()}>
             <img src={task.completionImage} onClick={() => onViewImage(task.completionImage!)} className="w-10 h-10 rounded-lg object-cover cursor-pointer hover:scale-105 transition-transform" />
             <span className="text-xs text-green-700 font-bold">Minh chứng hoàn thành</span>
         </div>
      )}

      <div className="mb-4 text-xs bg-gray-50 p-3 rounded-xl text-gray-600 border border-gray-100">
         <div className="flex justify-between mb-1.5"><span>Ngày giao:</span><span className="font-bold text-gray-800">{formatDateTime(task.createdAt)}</span></div>
         <div className="flex justify-between"><span>Hạn chót:</span><span className={`font-bold ${overdue ? 'text-red-600' : 'text-gray-800'}`}>{formatDateTime(task.dueDate)}</span></div>
      </div>

      <div className="flex items-center justify-between mb-4 border-b border-gray-50 pb-3">
         {creator && (
            <div className="flex items-center gap-2" title="Người giao việc">
                <div className="relative">
                   <img src={creator.avatar} className="w-6 h-6 rounded-full border border-gray-200" />
                   <div className="absolute -bottom-1 -right-1 bg-gray-200 text-[8px] px-1 rounded-full font-bold">G</div>
                </div>
                <span className="text-xs text-gray-600 truncate max-w-[80px]">{creator.name}</span>
            </div>
         )}
         <div className="text-gray-300 text-xs">→</div>
         {assignee && (
            <div className="flex items-center gap-2" title="Người thực hiện">
                <span className="text-xs text-gray-600 truncate max-w-[80px] text-right">{assignee.name}</span>
                <div className="relative">
                   <img src={assignee.avatar} className="w-6 h-6 rounded-full border border-gray-200" />
                   <div className="absolute -bottom-1 -right-1 bg-blue-100 text-blue-700 text-[8px] px-1 rounded-full font-bold">N</div>
                </div>
            </div>
         )}
      </div>

      <div className="flex items-center justify-between mt-auto" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center gap-2">
           <span className={`w-2.5 h-2.5 rounded-full ${task.status === TaskStatus.COMPLETED ? 'bg-green-500' : task.status === TaskStatus.IN_PROGRESS ? 'bg-blue-500' : 'bg-gray-300'}`}></span>
           <span className={`text-xs font-bold ${task.status === TaskStatus.COMPLETED ? 'text-green-600' : task.status === TaskStatus.IN_PROGRESS ? 'text-blue-600' : 'text-gray-500'}`}>
              {task.status === TaskStatus.COMPLETED ? 'Đã xong' : task.status === TaskStatus.IN_PROGRESS ? 'Đang làm' : 'Chờ xử lý'}
           </span>
        </div>

        <div className="flex gap-2">
          {isManager && task.status !== TaskStatus.COMPLETED && (
             <button onClick={() => onReassign(task)} className="text-xs font-bold text-gray-500 hover:text-navy-600 bg-white hover:bg-gray-50 px-3 py-2 rounded-lg border border-gray-200 shadow-sm transition-all" title="Giao lại"><IconShare className="w-3.5 h-3.5" /></button>
          )}
          {showAction && task.status !== TaskStatus.COMPLETED && (
            <button
              onClick={() => onStatusAction(task)}
              className="text-xs font-bold bg-navy-50 hover:bg-navy-100 text-navy-800 px-4 py-2 rounded-lg border border-navy-100 transition-colors shadow-sm"
            >
              {task.status === TaskStatus.TODO ? 'Bắt đầu' : 'Hoàn thành'}
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

import React, { useState, useRef, useEffect } from 'react';
import { User, UserRole, TaskPriority, Task } from '../types';
import { analyzeTaskAudio } from '../services/geminiService';
import { uploadTaskImage } from '../services/storageService';
import { IconMic, IconX, IconImage, IconAlert } from './Icons';

interface CreateTaskModalProps {
  currentUser: User;
  assignableUsers: User[]; 
  onClose: () => void;
  onCreate: (taskData: any) => Promise<void>;
  onEdit?: (taskData: any) => Promise<void>;
  initialData?: Task;
}

const CreateTaskModal: React.FC<CreateTaskModalProps> = ({ currentUser, assignableUsers, onClose, onCreate, onEdit, initialData }) => {
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [dueDate, setDueDate] = useState('');
  const [assigneeId, setAssigneeId] = useState(currentUser.id);
  const [priority, setPriority] = useState<TaskPriority>(TaskPriority.MEDIUM);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [isUploading, setIsUploading] = useState(false);

  // Image State
  const [selectedFiles, setSelectedFiles] = useState<File[]>([]);
  const [existingImages, setExistingImages] = useState<string[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Audio Recording Refs
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  const canAssign = currentUser.role === UserRole.MANAGER;

  // Load initial data if editing
  useEffect(() => {
    if (initialData) {
      setTitle(initialData.title);
      setDescription(initialData.description);
      // Format date for input datetime-local: YYYY-MM-DDTHH:mm
      try {
        const d = new Date(initialData.dueDate);
        // Adjust to local ISO string manually to handle timezone correctly for inputs
        const localIso = new Date(d.getTime() - (d.getTimezoneOffset() * 60000)).toISOString().slice(0, 16);
        setDueDate(localIso);
      } catch (e) {
        setDueDate('');
      }

      setAssigneeId(initialData.assigneeId);
      setPriority(initialData.priority);
      if (initialData.attachments) {
        setExistingImages(initialData.attachments);
      }
    }
  }, [initialData]);

  // Voice Command Logic
  const handleVoiceCommand = async () => {
    if (isRecording) {
      if (mediaRecorderRef.current && mediaRecorderRef.current.state === "recording") {
        mediaRecorderRef.current.stop();
        setIsRecording(false);
        setIsAnalyzing(true);
      }
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        const mediaRecorder = new MediaRecorder(stream);
        mediaRecorderRef.current = mediaRecorder;
        audioChunksRef.current = [];

        mediaRecorder.ondataavailable = (event: BlobEvent) => {
          if (event.data.size > 0) {
            audioChunksRef.current.push(event.data);
          }
        };

        mediaRecorder.onstop = async () => {
          const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
          const reader = new FileReader();
          reader.readAsDataURL(audioBlob);
          reader.onloadend = async () => {
            const base64String = reader.result as string;
            const base64Data = base64String.split(',')[1];
            const transcription = await analyzeTaskAudio(base64Data, audioBlob.type || 'audio/webm');

            if (transcription) {
              if (!title) {
                setTitle(transcription);
              } else {
                setDescription(prev => (prev ? prev + '\n' + transcription : transcription));
              }
            }
            setIsAnalyzing(false);
            stream.getTracks().forEach(track => track.stop());
          };
        };

        mediaRecorder.start();
        setIsRecording(true);
      } catch (err) {
        console.error("Error accessing microphone:", err);
        alert("Không thể truy cập Microphone. Vui lòng kiểm tra quyền truy cập.");
      }
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const filesArray: File[] = Array.from(e.target.files);
      // Validate file size (e.g., max 5MB)
      const oversizedFiles = filesArray.filter(f => f.size > 5 * 1024 * 1024);
      if (oversizedFiles.length > 0) {
        alert("Một số ảnh quá lớn (>5MB) và sẽ bị bỏ qua.");
      }
      const validFiles = filesArray.filter(f => f.size <= 5 * 1024 * 1024);
      setSelectedFiles(prev => [...prev, ...validFiles]);
    }
  };

  const removeSelectedFile = (index: number) => {
    setSelectedFiles(prev => prev.filter((_, i) => i !== index));
  };

  const removeExistingImage = (url: string) => {
    setExistingImages(prev => prev.filter(img => img !== url));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title || !dueDate) {
       alert("Vui lòng nhập tiêu đề và hạn chót!");
       return;
    }

    setIsUploading(true);

    try {
      const tempTaskId = initialData?.id || Math.random().toString(36).substr(2, 9);

      // Upload images
      const uploadPromises = selectedFiles.map(file => uploadTaskImage(file, tempTaskId));
      const results = await Promise.all(uploadPromises);

      // Filter successful uploads
      const validNewUrls = results.filter(url => url !== null) as string[];

      // Error handling for uploads
      if (selectedFiles.length > 0 && validNewUrls.length === 0) {
         const continueSave = window.confirm("Không thể tải ảnh lên (Lỗi kết nối hoặc quyền truy cập). Bạn có muốn tiếp tục lưu công việc mà không có ảnh mới?");
         if (!continueSave) {
           setIsUploading(false);
           return;
         }
      } else if (selectedFiles.length > validNewUrls.length) {
         alert(`Cảnh báo: Chỉ tải lên được ${validNewUrls.length}/${selectedFiles.length} ảnh.`);
      }

      const allAttachments = [...existingImages, ...validNewUrls];

      const data = {
        id: tempTaskId, 
        title,
        description,
        dueDate: new Date(dueDate).toISOString(),
        assigneeId: canAssign ? assigneeId : currentUser.id,
        priority,
        attachments: allAttachments
      };

      if (initialData && onEdit) {
        await onEdit({ ...initialData, ...data });
      } else {
        await onCreate(data);
      }
      onClose(); // Close strictly after success
    } catch (error) {
      console.error("Error saving task:", error);
      alert("Có lỗi xảy ra khi lưu công việc. Vui lòng thử lại.");
    } finally {
      setIsUploading(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/50 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 backdrop-blur-sm animate-fade-in">
      <div className="bg-white w-full sm:max-w-lg rounded-t-2xl sm:rounded-2xl p-6 shadow-2xl animate-slide-up sm:animate-none max-h-[90vh] overflow-y-auto custom-scrollbar flex flex-col">
        <div className="flex justify-between items-center mb-6 border-b border-gray-100 pb-4">
          <h2 className="text-xl font-bold text-navy-800">
            {initialData ? 'Sửa Công Việc' : 'Giao Việc Mới'}
          </h2>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600 p-2 rounded-full hover:bg-gray-100"><IconX className="w-5 h-5"/></button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-5">

          {/* Title Input */}
          <div>
            <label className="block text-sm font-bold text-gray-700 mb-1">Nhiệm vụ <span className="text-red-500">*</span></label>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="VD: Báo cáo thu chi tháng 12..."
              className="w-full p-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-navy-800 outline-none transition-all font-medium"
              required={!isRecording}
              disabled={isUploading}
            />
          </div>

          {/* Description Input with Voice */}
          <div>
            <label className="block text-sm font-bold text-gray-700 mb-1">Mô tả chi tiết</label>
            <div className="relative">
               <textarea
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                rows={4}
                className="w-full p-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-navy-800 outline-none resize-none transition-all text-sm"
                placeholder="Chi tiết công việc..."
                disabled={isUploading}
              />
              <button
                type="button"
                onClick={handleVoiceCommand}
                disabled={isAnalyzing || isUploading}
                className={`absolute bottom-3 right-3 p-2 rounded-full shadow-sm transition-all ${
                  isRecording ? 'bg-red-500 text-white animate-pulse' : 
                  isAnalyzing ? 'bg-yellow-400 text-white' : 'bg-gray-100 text-gray-500 hover:bg-gray-200'
                }`}
                title="Nhập bằng giọng nói (AI)"
              >
                <IconMic className="w-4 h-4" />
              </button>
            </div>
            {isAnalyzing && <p className="text-xs text-yellow-600 mt-1 font-medium italic">Đang phân tích giọng nói...</p>}
          </div>

          {/* Image Upload Area */}
          <div>
             <label className="block text-sm font-bold text-gray-700 mb-2">Hình ảnh đính kèm</label>

             {/* Preview Grid */}
             <div className="grid grid-cols-4 gap-2 mb-3">
                {existingImages.map((url, idx) => (
                   <div key={`exist-${idx}`} className="relative group aspect-square rounded-lg overflow-hidden border border-gray-200">
                      <img src={url} className="w-full h-full object-cover" />
                      <button type="button" onClick={() => removeExistingImage(url)} className="absolute top-0.5 right-0.5 bg-red-500 text-white rounded-full p-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
                        <IconX className="w-3 h-3"/>
                      </button>
                   </div>
                ))}
                {selectedFiles.map((file, idx) => (
                   <div key={`new-${idx}`} className="relative group aspect-square rounded-lg overflow-hidden border border-gray-200">
                      <img src={URL.createObjectURL(file)} className="w-full h-full object-cover" />
                      <div className="absolute inset-0 bg-green-500/10 pointer-events-none"></div> {/* Indicator for new files */}
                      <button type="button" onClick={() => removeSelectedFile(idx)} className="absolute top-0.5 right-0.5 bg-red-500 text-white rounded-full p-0.5">
                        <IconX className="w-3 h-3"/>
                      </button>
                   </div>
                ))}

                {/* Add Button */}
                <button 
                  type="button" 
                  onClick={() => fileInputRef.current?.click()}
                  className="aspect-square rounded-lg border-2 border-dashed border-gray-300 flex flex-col items-center justify-center text-gray-400 hover:border-navy-500 hover:text-navy-500 hover:bg-gray-50 transition-all"
                  disabled={isUploading}
                >
                   <IconImage className="w-6 h-6 mb-1"/>
                </button>
             </div>
             <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleFileSelect} 
                className="hidden" 
                multiple 
                accept="image/*" 
             />
          </div>

          {/* Row: Due Date & Priority */}
          <div className="grid grid-cols-2 gap-4">
             <div>
                <label className="block text-sm font-bold text-gray-700 mb-1">Hạn chót <span className="text-red-500">*</span></label>
                <input
                  type="datetime-local"
                  value={dueDate}
                  onChange={(e) => setDueDate(e.target.value)}
                  className="w-full p-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-navy-800 outline-none text-sm font-medium"
                  required
                  disabled={isUploading}
                />
             </div>
             <div>
                <label className="block text-sm font-bold text-gray-700 mb-1">Độ ưu tiên</label>
                <select
                  value={priority}
                  onChange={(e) => setPriority(e.target.value as TaskPriority)}
                  className="w-full p-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-navy-800 outline-none text-sm bg-white"
                  disabled={isUploading}
                >
                  <option value={TaskPriority.LOW}>Thấp</option>
                  <option value={TaskPriority.MEDIUM}>Trung bình</option>
                  <option value={TaskPriority.HIGH}>Cao</option>
                  <option value={TaskPriority.URGENT}>Khẩn cấp</option>
                </select>
             </div>
          </div>

          {/* Assignee (Manager Only) */}
          {canAssign && (
            <div>
              <label className="block text-sm font-bold text-gray-700 mb-1">Giao cho nhân viên</label>
              <select
                value={assigneeId}
                onChange={(e) => setAssigneeId(e.target.value)}
                className="w-full p-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-navy-800 outline-none text-sm bg-white"
                disabled={isUploading}
              >
                {assignableUsers.map(user => (
                  <option key={user.id} value={user.id}>
                    {user.name} ({user.username})
                  </option>
                ))}
              </select>
            </div>
          )}

          {/* Submit Button */}
          <button
            type="submit"
            disabled={isUploading}
            className={`w-full py-4 rounded-xl font-bold text-white shadow-lg transition-all flex items-center justify-center gap-2 mt-4 ${
               isUploading ? 'bg-gray-400 cursor-not-allowed' : 'bg-navy-800 hover:bg-navy-900 active:scale-[0.98]'
            }`}
          >
            {isUploading ? (
               <>
                 <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                 <span>Đang tải ảnh lên...</span>
               </>
            ) : (
               initialData ? 'Lưu thay đổi' : 'Giao việc ngay'
            )}
          </button>
        </form>
      </div>
    </div>
  );
};

export default CreateTaskModal;

import { 
  collection, 
  addDoc, 
  updateDoc, 
  deleteDoc, 
  doc, 
  query, 
  where, 
  onSnapshot,
  getDocs,
  setDoc,
  writeBatch
} from "firebase/firestore";
import { 
  ref, 
  uploadBytes, 
  getDownloadURL, 
  deleteObject, 
  listAll 
} from "firebase/storage";
import { db, storage } from "./firebaseConfig";
import { User, Task, TaskStatus } from '../types';

// Collection Names
const USERS_COL = 'users';
const TASKS_COL = 'tasks';

// --- HELPER: Sanitize Data for Firestore ---
const sanitizePayload = (data: any) => {
  if (!data || typeof data !== 'object') return data;

  const clean = { ...data };
  Object.keys(clean).forEach(key => {
    if (clean[key] === undefined) {
      clean[key] = null;
    }
  });
  return clean;
};

// --- SESSION MANAGEMENT ---
export const getStoredSession = (): User | null => {
  try {
    const data = localStorage.getItem('biz_session');
    return data ? JSON.parse(data) : null;
  } catch (error) {
    return null;
  }
};

export const saveStoredSession = (user: User | null) => {
  if (user) {
    localStorage.setItem('biz_session', JSON.stringify(user));
  } else {
    localStorage.removeItem('biz_session');
  }
};

// --- REAL-TIME LISTENERS ---

export const subscribeToUsers = (companyId: string, callback: (users: User[]) => void) => {
  if (!db) return () => {};

  const q = query(collection(db, USERS_COL), where("companyId", "==", companyId));

  const unsubscribe = onSnapshot(q, (snapshot) => {
    const users: User[] = [];
    snapshot.forEach((doc) => {
      users.push({ ...doc.data(), id: doc.id } as User);
    });
    callback(users);
  });

  return unsubscribe;
};

export const subscribeToTasks = (companyId: string, callback: (tasks: Task[]) => void) => {
  if (!db) return () => {};

  const q = query(collection(db, TASKS_COL), where("companyId", "==", companyId));

  const unsubscribe = onSnapshot(q, (snapshot) => {
    const tasks: Task[] = [];
    snapshot.forEach((doc) => {
      tasks.push({ ...doc.data(), id: doc.id } as Task);
    });
    tasks.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
    callback(tasks);
  });

  return unsubscribe;
};

// --- STORAGE OPERATIONS (Images) ---

export const uploadTaskImage = async (file: File, taskId: string): Promise<string | null> => {
  if (!storage) {
    console.error("Storage not initialized");
    alert("Lỗi: Firebase Storage chưa được khởi tạo. Hãy kiểm tra kết nối mạng.");
    return null;
  }
  try {
    // Tạo tên file unique bằng timestamp
    const safeName = file.name.replace(/[^a-zA-Z0-9.]/g, '_');
    const fileName = `${Date.now()}_${safeName}`;
    const storageRef = ref(storage, `task_images/${taskId}/${fileName}`);

    const metadata = {
      contentType: file.type,
    };

    const snapshot = await uploadBytes(storageRef, file, metadata);
    const url = await getDownloadURL(snapshot.ref);
    return url;
  } catch (e: any) {
    console.error("Upload image failed DETAILED:", e);

    // Phân loại lỗi để người dùng biết cách sửa
    if (e.code === 'storage/unauthorized') {
       alert("Lỗi Quyền (Unauthorized): Bạn cần vào Firebase Console > Storage > Rules và cho phép 'allow read, write;'.");
    } else if (e.code === 'storage/canceled') {
       alert("Đã hủy tải lên.");
    } else if (e.message && e.message.includes('network')) {
       // Lỗi CORS thường bị trình duyệt báo là Network Error
       alert("Lỗi Cấu Hình Server (CORS): Firebase chặn tên miền của bạn. Hãy làm theo hướng dẫn sửa lỗi CORS bằng gsutil.");
    } else {
       alert(`Lỗi không xác định khi tải ảnh: ${e.message || e}`);
    }
    return null;
  }
};

// Xóa toàn bộ ảnh trong thư mục của 1 Task
export const deleteTaskAssets = async (taskId: string) => {
  if (!storage) return;
  const folderRef = ref(storage, `task_images/${taskId}`);
  try {
    const listResult = await listAll(folderRef);
    const deletePromises = listResult.items.map(item => deleteObject(item));
    await Promise.all(deletePromises);
    console.log(`Deleted assets for task ${taskId}`);
  } catch (e) {
    // Nếu folder không tồn tại hoặc lỗi, cứ bỏ qua
    console.log("No assets to delete or error", e);
  }
};

