export const subscribeToUsers = (companyId: string, callback: (users: User[]) => void) => {
  if (!db) return () => {};

  const q = query(collection(db, USERS_COL), where("companyId", "==", companyId));

  const unsubscribe = onSnapshot(q, (snapshot) => {
    const users: User[] = [];
    snapshot.forEach((doc) => {
      users.push({ ...doc.data(), id: doc.id } as User);
    });
    callback(users);
  });

  return unsubscribe;
};

export const subscribeToTasks = (companyId: string, callback: (tasks: Task[]) => void) => {
  if (!db) return () => {};

  const q = query(collection(db, TASKS_COL), where("companyId", "==", companyId));

  const unsubscribe = onSnapshot(q, (snapshot) => {
    const tasks: Task[] = [];
    snapshot.forEach((doc) => {
      tasks.push({ ...doc.data(), id: doc.id } as Task);
    });
    tasks.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
    callback(tasks);
  });

  return unsubscribe;
};

// --- STORAGE OPERATIONS (Images) ---

export const uploadTaskImage = async (file: File, taskId: string): Promise<string | null> => {
  if (!storage) {
    console.error("Storage not initialized");
    alert("Lỗi: Firebase Storage chưa được khởi tạo. Hãy kiểm tra kết nối mạng.");
    return null;
  }
  try {
    // Tạo tên file unique bằng timestamp
    const safeName = file.name.replace(/[^a-zA-Z0-9.]/g, '_');
    const fileName = `${Date.now()}_${safeName}`;
    const storageRef = ref(storage, `task_images/${taskId}/${fileName}`);

    const metadata = {
      contentType: file.type,
    };

    const snapshot = await uploadBytes(storageRef, file, metadata);
    const url = await getDownloadURL(snapshot.ref);
    return url;
  } catch (e: any) {
    console.error("Upload image failed DETAILED:", e);

    const errString = e.message || e.toString();
    const errCode = e.code || '';

    // 1. Lỗi chưa tạo Bucket (Phổ biến nhất với project mới)
    if (errString.includes('404') || errCode === 'storage/object-not-found' || errCode === 'storage/bucket-not-found') {
        alert("LỖI 404 (Chưa tạo Bucket):\n\nBạn chưa kích hoạt Storage trong Console hoặc tên Bucket bị sai.\n\n--> Hãy vào Firebase Console > Build > Storage và bấm nút 'Get Started' để tạo kho lưu trữ.");
    } 
    // 2. Lỗi chưa set Rule (Quyền truy cập)
    else if (errCode === 'storage/unauthorized') {
       alert("LỖI QUYỀN (403):\n\nFirebase đang chặn ghi file.\n\n--> Vào Console > Storage > Rules và sửa thành: 'allow read, write: if true;'");
    } 
    // 3. Lỗi CORS (Chặn tên miền)
    else if (errString.includes('network') || errString.includes('retry')) {
       alert("LỖI CORS (Chặn tên miền):\n\nServer từ chối kết nối từ trang web này.\n\n--> Mở Cloud Shell và chạy lệnh gsutil cors set... như hướng dẫn.");
    } 
    // 4. Lỗi khác
    else {
       alert(`Lỗi không xác định (${errCode}): ${errString}`);
    }
    return null;
  }
};

