          await Badge.set({ count });
        } else {
          await Badge.clear();
        }
      } else {
        if ('setAppBadge' in navigator) {
          if (count > 0) {
            navigator.setAppBadge(count).catch(e => console.error("Set badge error", e));
          } else {
            navigator.clearAppBadge().catch(e => console.error("Clear badge error", e));
          }
        }
      }
    } catch (e) {
      console.error("Badge Error:", e);
    }
  };

  useEffect(() => {
    updateAppBadge(myPendingTaskCount);
    const handleVisibilityChange = () => {
      if (document.visibilityState === 'hidden') {
        updateAppBadge(myPendingTaskCount);
      }
    };
    document.addEventListener('visibilitychange', handleVisibilityChange);
    return () => {
      document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, [myPendingTaskCount, isNative]);

  const requestNotificationAccess = async () => {
    if (isNative) {
       await Badge.requestPermissions();
       alert("Đã yêu cầu quyền thông báo.");
       return;
    }
    if (!('Notification' in window)) return;
    const permission = await Notification.requestPermission();
    setNotificationPermission(permission);
    if (permission === 'granted') updateAppBadge(myPendingTaskCount);
  };

  const testBadge = async () => {
     try {
       const randomNum = Math.floor(Math.random() * 10) + 1;
       if (isNative) {
         await Badge.set({ count: randomNum });
         alert(`[Native] Badge: ${randomNum}`);
       } else {
         if ('setAppBadge' in navigator) {
            await navigator.setAppBadge(randomNum);
            alert(`[Web] Badge: ${randomNum}`);
         }
       }
     } catch (e: any) {
       alert(`Lỗi: ${e.message}`);
     }
  };

  const handleRegisterCompany = (newUser: User) => {
    setCurrentUser(newUser);
    setActiveTab('dashboard');
  };

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    setActiveTab('dashboard');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    updateAppBadge(0);
  };

  const handleAddUser = async (newUser: User) => {
    await apiAddUser(newUser);
  };

  const handleDeleteUser = async (userId: string) => {
    await apiDeleteUser(userId);
  };

  const handleChangeSelfPass = async () => {
    if(!currentUser || !newSelfPass) return;
    try {
      const updatedUser = { ...currentUser, password: newSelfPass };
      await apiUpdateUser(updatedUser);
      setCurrentUser(updatedUser);
      setNewSelfPass('');
      setShowChangePassModal(false);
      alert('Đổi mật khẩu thành công!');
    } catch (e) {
      alert('Có lỗi xảy ra, vui lòng thử lại.');
    }
  };

  const handleUpdateAvatar = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!currentUser || !e.target.files || !e.target.files[0]) return;
    const file = e.target.files[0];

    // REMOVED 2MB Check to allow larger files to be compressed
    // if (file.size > 2 * 1024 * 1024) { ... }

    try {
      const base64Img = await compressImageToBase64(file);
      const updatedUser = { ...currentUser, avatar: base64Img };

      // Update DB
      await apiUpdateUser(updatedUser);

      // Update State immediately
      setCurrentUser(updatedUser);

    } catch (error) {
      console.error("Avatar update failed:", error);
      alert("Lỗi cập nhật ảnh đại diện.");
    }
  };

  // --- Task Operations ---
  const createTask = async (taskData: any) => {
    if (!currentUser) return;
    const newTask: Task = {
      id: taskData.id || Math.random().toString(36).substr(2, 9),
      companyId: currentUser.companyId,
      ...taskData,
      status: TaskStatus.TODO,
      creatorId: currentUser.id,
      createdAt: new Date().toISOString()
    };
    await apiAddTask(newTask);
    setShowCreateModal(false);
  };

  const handleEditTask = (task: Task) => {
      setEditingTask(task);
  };

  const submitEditTask = async (updatedData: Task) => {
      await apiUpdateTask(updatedData);
      setEditingTask(null); 
  };

  const handleStatusClick = (task: Task) => {
    if (task.status === TaskStatus.TODO) {
      updateTaskStatus(task.id, TaskStatus.IN_PROGRESS);
      // UX IMPROVEMENT: Nếu đang lọc theo "Chờ xử lý", tự động chuyển sang "Tất cả"
      // để công việc vừa bấm không bị biến mất khỏi màn hình.
      // Với logic sắp xếp mới (In Progress -> Todo), công việc sẽ nhảy lên đầu danh sách.
      if (statusFilter === TaskStatus.TODO) {
        setStatusFilter('ALL');
      }
    } else if (task.status === TaskStatus.IN_PROGRESS) {
      setCompletingTask(task);
      setCompletionFile(null);
      setShowCompleteModal(true);
    }
  };

  const confirmCompleteTask = async () => {
    if (!completingTask) return;
    setIsSubmittingComplete(true);

    let imageUrl = '';
    if (completionFile) {
       const url = await uploadTaskImage(completionFile, completingTask.id);
       if (url) imageUrl = url;
    }

    const updatedTask = {
      ...completingTask,
      status: TaskStatus.COMPLETED,
      completedAt: new Date().toISOString(),
      completionImage: imageUrl || undefined
    };

    await apiUpdateTask(updatedTask);
    setIsSubmittingComplete(false);
    setShowCompleteModal(false);
    setCompletingTask(null);
  };

  const updateTaskStatus = async (taskId: string, newStatus: TaskStatus) => {
    const task = tasks.find(t => t.id === taskId);
    if (!task) return;
    const updatedTask = {
      ...task,
      status: newStatus,
      completedAt: newStatus === TaskStatus.COMPLETED ? new Date().toISOString() : null
    };
    await apiUpdateTask(updatedTask);
  };

  const handleReassign = async (userId: string) => {
    if (!reassignTask) return;
    const updatedTask = { ...reassignTask, assigneeId: userId };
    await apiUpdateTask(updatedTask);
    setReassignTask(null);
  };

  // --- Filter Logic ---

  const myRelevantTasks = useMemo(() => {
    if (!currentUser) return [];
    if (currentUser.role === UserRole.MANAGER) {
      return tasks;
    }
    return tasks.filter(t => t.assigneeId === currentUser.id);
  }, [tasks, currentUser]);

  const filteredTasks = useMemo(() => {
    let result = [...myRelevantTasks];

    // UPDATED SORTING LOGIC: In Progress -> Todo -> Completed
    result.sort((a, b) => {
       // 1. Completed always at bottom
       if (a.status === TaskStatus.COMPLETED && b.status !== TaskStatus.COMPLETED) return 1;
       if (a.status !== TaskStatus.COMPLETED && b.status === TaskStatus.COMPLETED) return -1;

       // 2. IN_PROGRESS always at TOP (Active work)
       if (a.status === TaskStatus.IN_PROGRESS && b.status !== TaskStatus.IN_PROGRESS) return -1;
       if (a.status !== TaskStatus.IN_PROGRESS && b.status === TaskStatus.IN_PROGRESS) return 1;

       // 3. Sort by Due Date (Urgent first)
       return new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime();
    });

    if (statusFilter === 'OVERDUE') {
      result = result.filter(t => t.status !== TaskStatus.COMPLETED && isOverdue(t.dueDate));
    } else if (statusFilter !== 'ALL') {
      result = result.filter(t => t.status === statusFilter);
    }

    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      result = result.filter(t => 
        t.title.toLowerCase().includes(q) || 
        t.description.toLowerCase().includes(q)
      );
    }

    if (startDate || endDate) {
      result = result.filter(t => {
        const taskDate = new Date(t.dueDate).toISOString().split('T')[0];
        let inRange = true;
        if (startDate && taskDate < startDate) inRange = false;
        if (endDate && taskDate > endDate) inRange = false;
        return inRange;
      });
    }

    return result;
  }, [myRelevantTasks, statusFilter, searchQuery, startDate, endDate]);

  const stats = useMemo(() => {
    const defaultStats = { 
        pending: 0, 
        inProgress: 0, 
        overdueTotal: 0,
        dueSoonTotal: 0,
        urgentTotal: 0,
        overdueMonth: 0, 
        completedMonth: 0, 
        overdueRate: 0 
    };

    if (!currentUser) return defaultStats;

    const sourceTasks = currentUser.role === UserRole.MANAGER ? tasks : myRelevantTasks;

    const pending = sourceTasks.filter(t => t.status === TaskStatus.TODO).length;
    const inProgress = sourceTasks.filter(t => t.status === TaskStatus.IN_PROGRESS).length;
    const overdueTotal = sourceTasks.filter(t => t.status !== TaskStatus.COMPLETED && isOverdue(t.dueDate)).length;
    const dueSoonTotal = sourceTasks.filter(t => t.status !== TaskStatus.COMPLETED && !isOverdue(t.dueDate) && isDueSoon(t.dueDate, 3)).length;
    const urgentTotal = overdueTotal + dueSoonTotal;

    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();

    const tasksDueThisMonth = sourceTasks.filter(t => {
      const d = new Date(t.dueDate);
      return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });

    const completedMonth = sourceTasks.filter(t => {
       if (t.status !== TaskStatus.COMPLETED) return false;
       const d = new Date(t.completedAt || t.dueDate); 
       return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    }).length;

    const overdueMonth = tasksDueThisMonth.filter(t => 
        t.status !== TaskStatus.COMPLETED && isOverdue(t.dueDate)
    ).length;

    const totalProcessedThisMonth = completedMonth + overdueMonth + 
        tasksDueThisMonth.filter(t => t.status === TaskStatus.TODO || t.status === TaskStatus.IN_PROGRESS).length;

    const overdueRate = totalProcessedThisMonth > 0 ? Math.round((overdueMonth / totalProcessedThisMonth) * 100) : 0;

    return { 
        pending, 
        inProgress, 
        overdueTotal,
        dueSoonTotal,
        urgentTotal,
        overdueMonth,
        completedMonth, 
        overdueRate
    };
  }, [tasks, myRelevantTasks, currentUser]);

  const chartData = useMemo(() => {
     if (!currentUser) return [];
     const sourceTasks = currentUser.role === UserRole.MANAGER ? tasks : myRelevantTasks;
     const data = [];
     const now = new Date();

     // Last 12 months
     for (let i = 11; i >= 0; i--) {
        const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
        const month = d.getMonth();
        const year = d.getFullYear();

        const count = sourceTasks.filter(t => {
           if (t.status !== TaskStatus.COMPLETED || !t.completedAt) return false;
           const cDate = new Date(t.completedAt);
           return cDate.getMonth() === month && cDate.getFullYear() === year;
        }).length;

        data.push({ 
           label: `T${month + 1}`, 
           count,
           fullLabel: `Tháng ${month + 1}/${year}`
        });
     }
     return data;
  }, [tasks, myRelevantTasks, currentUser]);

  const maxChartValue = useMemo(() => {
     return Math.max(...chartData.map(d => d.count), 5); // Minimum scale of 5
  }, [chartData]);

  const teamStats = useMemo(() => {
    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();

    const stats = users.map(user => {
      const userTasks = tasks.filter(t => t.assigneeId === user.id);
      const todo = userTasks.filter(t => t.status === TaskStatus.TODO).length;
      const doing = userTasks.filter(t => t.status === TaskStatus.IN_PROGRESS).length;
      const done = userTasks.filter(t => t.status === TaskStatus.COMPLETED).length;
      const overdue = userTasks.filter(t => t.status !== TaskStatus.COMPLETED && isOverdue(t.dueDate)).length;

      // Calculate monthly productivity
      const completedThisMonth = userTasks.filter(t => {
         if (t.status !== TaskStatus.COMPLETED) return false;
         const d = new Date(t.completedAt || t.dueDate);
         return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      });

      const doneMonthCount = completedThisMonth.length;
      const overdueDoneMonth = completedThisMonth.filter(t => {
         // Task is considered "late" if completedAt > dueDate
         if(!t.completedAt) return false;
         return new Date(t.completedAt) > new Date(t.dueDate);
      }).length;

      const onTimeRate = doneMonthCount > 0 
         ? Math.round(((doneMonthCount - overdueDoneMonth) / doneMonthCount) * 100) 
         : 0;

      return { user, todo, doing, done, overdue, doneMonthCount, onTimeRate };
    });

    // Sort by Pending Tasks (Todo) Descending
    return stats.sort((a, b) => b.todo - a.todo);

  }, [users, tasks]);

  const selectedEmployeeTasks = useMemo(() => {
    if (!selectedEmployee) return [];
    const list = tasks.filter(t => t.assigneeId === selectedEmployee.id);
    list.sort((a, b) => {
        const isAComplete = a.status === TaskStatus.COMPLETED;
        const isBComplete = b.status === TaskStatus.COMPLETED;
        if (isAComplete !== isBComplete) return isAComplete ? 1 : -1;
        return new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime();
    });
    return list;
  }, [tasks, selectedEmployee]);

  const navigateToMonthStats = (status: TaskStatus | 'OVERDUE') => {
      const now = new Date();
      const firstDay = new Date(now.getFullYear(), now.getMonth(), 1);
      const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0);

      const format = (d: Date) => d.toISOString().split('T')[0];

      setStartDate(format(firstDay));
      setEndDate(format(lastDay));
      setStatusFilter(status);
      setActiveTab('tasks');
  };

  const resetFilters = () => {
      setStartDate('');
      setEndDate('');
      setStatusFilter('ALL');
  };

  if (!isSystemReady) return <SetupScreen />;
  if (!currentUser) return <Auth onLogin={handleLogin} onRegisterCompany={handleRegisterCompany} />;

  return (
    <div className="flex flex-col h-full bg-slate-50 font-sans">
      {/* HEADER */}
      <header className="bg-navy-800 px-6 py-4 shadow-md flex justify-between items-center sticky top-0 z-10">
        <div>
          <h1 className="text-xl font-bold text-white tracking-wide">
            {activeTab === 'dashboard' ? 'Tổng quan' : 
             activeTab === 'tasks' ? 'Danh sách việc' : 
             activeTab === 'team' ? 'Nhân sự' : 'Hồ sơ'}
          </h1>
          <div className="flex items-center gap-1 text-xs text-blue-200 mt-1">
            <IconBuilding className="w-3 h-3" />
            <span className="uppercase font-bold tracking-wider">{currentUser.companyName}</span>
          </div>
        </div>
        <div className="flex items-center gap-3">
           <div className={`w-2.5 h-2.5 rounded-full border-2 border-navy-900 ${isLoadingData ? 'bg-yellow-400 animate-pulse' : 'bg-green-400'}`} title={isLoadingData ? 'Đang tải...' : 'Online'}></div>
           <img src={currentUser.avatar} alt="Avatar" className="w-10 h-10 rounded-full border-2 border-navy-700 object-cover shadow-sm" />
        </div>
      </header>

      {/* MAIN CONTENT */}
      <main className="flex-1 overflow-y-auto hide-scrollbar p-4 pb-24 w-full max-w-7xl mx-auto">
        {activeTab === 'dashboard' && (
          <div className="space-y-6">
            <div className="text-sm text-gray-500 font-medium">
                Chào <span className="text-navy-800 font-bold text-base">{currentUser.name}</span>, chúc bạn một ngày làm việc hiệu quả!
            </div>

            {/* DASHBOARD LAYOUT */}
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">

                {/* 1. ALERTS & TILES (Top on Mobile, Left on Desktop) */}
                <div className="lg:col-span-8 space-y-6">

                    {/* ALERT MODULE */}
                    <div className="bg-white p-1 rounded-2xl shadow-sm border border-red-100">
                        {stats.urgentTotal > 0 ? (
                            <button 
                                onClick={() => { setStartDate(''); setEndDate(''); setStatusFilter('ALL'); setActiveTab('tasks'); }}
                                className="w-full bg-gradient-to-r from-red-600 to-rose-500 text-white p-5 rounded-xl flex items-center justify-between shadow-md hover:shadow-lg transition-all group"
                            >
                                <div className="flex items-center gap-4">
                                <div className="bg-white/20 p-2.5 rounded-xl group-hover:scale-110 transition-transform animate-bounce"><IconAlert className="w-6 h-6" /></div>
                                <div className="text-left">
                                    <h3 className="font-bold text-lg">Cảnh báo khẩn cấp!</h3>
                                    <p className="text-red-100 text-sm font-medium">
                                       Có <span className="font-bold underline">{stats.overdueTotal} quá hạn</span> & <span className="font-bold underline">{stats.dueSoonTotal} sắp đến hạn</span>.
                                    </p>
                                </div>
                                </div>
                                <div className="text-3xl font-bold bg-white/20 w-14 h-14 flex items-center justify-center rounded-xl shadow-inner">{stats.urgentTotal}</div>
                            </button>
                        ) : (
                            <div className="w-full bg-gradient-to-r from-green-600 to-emerald-500 text-white p-5 rounded-xl flex items-center gap-4 shadow-md">
                                <div className="bg-white/20 p-2.5 rounded-xl"><IconCheck className="w-6 h-6" /></div>
                                <div>
                                    <h3 className="font-bold text-lg">Mọi thứ ổn định!</h3>
                                    <p className="text-green-100 text-sm">Không có công việc nào cần xử lý gấp.</p>
                                </div>
                            </div>
                        )}
                    </div>

                    {/* TILES */}
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                        <div onClick={() => { setStartDate(''); setEndDate(''); setStatusFilter('ALL'); setActiveTab('tasks'); }} className="bg-white p-4 rounded-2xl shadow-sm border-b-4 border-yellow-400 flex flex-col items-center justify-center gap-2 text-center cursor-pointer hover:shadow-md hover:-translate-y-1 transition-all h-32">
                            <span className="w-8 h-8 rounded-full bg-yellow-100 flex items-center justify-center text-yellow-700"><IconClock className="w-4 h-4" /></span>
                            <span className="text-2xl font-bold text-gray-800">{stats.pending}</span>
                            <span className="text-[10px] font-bold text-gray-500 uppercase tracking-wide">Chờ xử lý</span>
                        </div>
                        <div onClick={() => { setStartDate(''); setEndDate(''); setStatusFilter('ALL'); setActiveTab('tasks'); }} className="bg-white p-4 rounded-2xl shadow-sm border-b-4 border-blue-500 flex flex-col items-center justify-center gap-2 text-center cursor-pointer hover:shadow-md hover:-translate-y-1 transition-all h-32">
                            <span className="w-8 h-8 rounded-full bg-blue-100 flex items-center justify-center text-blue-700"><IconList className="w-4 h-4" /></span>
                            <span className="text-2xl font-bold text-gray-800">{stats.inProgress}</span>
                            <span className="text-[10px] font-bold text-gray-500 uppercase tracking-wide">Đang làm</span>
                        </div>
                        <div onClick={() => navigateToMonthStats(TaskStatus.COMPLETED)} className="bg-white p-4 rounded-2xl shadow-sm border-b-4 border-green-500 flex flex-col items-center justify-center gap-2 text-center cursor-pointer hover:shadow-md hover:-translate-y-1 transition-all h-32">
                            <span className="w-8 h-8 rounded-full bg-green-100 flex items-center justify-center text-green-700"><IconCheck className="w-4 h-4" /></span>
                            <span className="text-2xl font-bold text-gray-800">{stats.completedMonth}</span>
                            <span className="text-[10px] font-bold text-gray-500 uppercase tracking-wide">Xong (T{new Date().getMonth() + 1})</span>
                        </div>
                        <div onClick={() => navigateToMonthStats('OVERDUE')} className="bg-white p-4 rounded-2xl shadow-sm border-b-4 border-red-500 flex flex-col items-center justify-center gap-2 text-center cursor-pointer hover:shadow-md hover:-translate-y-1 transition-all h-32">
                            <span className="w-8 h-8 rounded-full bg-red-100 flex items-center justify-center text-red-700"><IconAlert className="w-4 h-4" /></span>
                            <span className="text-2xl font-bold text-gray-800">{stats.overdueMonth}</span>
                            <span className="text-[10px] font-bold text-gray-500 uppercase tracking-wide">Trễ (T{new Date().getMonth() + 1})</span>
                        </div>
                    </div>
                </div>

                {/* 2. MONTH SUMMARY (Middle on Mobile, Right on Desktop) */}
                <div className="lg:col-span-4 lg:row-span-2 space-y-6">
                    <div className="bg-navy-900 p-5 rounded-2xl shadow-xl text-white relative overflow-hidden group">
                        <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity"><IconChart className="w-32 h-32" /></div>
                        <div className="relative z-10">
                            <h3 className="text-base font-bold mb-4 flex items-center gap-2 border-b border-navy-700 pb-2">
                               Tổng kết Tháng {new Date().getMonth() + 1}
                            </h3>

                            <div className="space-y-4">
                                <div className="flex justify-between items-center">
                                    <span className="text-blue-200 text-xs">Tổng việc được giao</span>
                                    <span className="font-bold text-xl">{stats.completedMonth + stats.pending + stats.inProgress}</span>
                                </div>
                                <div className="flex justify-between items-center">
                                    <span className="text-green-300 text-xs">Đã hoàn thành</span>
                                    <span className="font-bold text-xl text-green-400">{stats.completedMonth}</span>
                                </div>

                                <div className="w-full bg-navy-700 h-1.5 rounded-full mt-2 overflow-hidden">
                                    <div className="bg-green-400 h-full transition-all duration-1000" style={{ width: `${(stats.completedMonth / (stats.completedMonth + stats.pending + stats.inProgress || 1)) * 100}%` }}></div>
                                </div>

                                <div className="pt-4 border-t border-navy-700 mt-2 flex items-center justify-between">
                                     <div className="flex flex-col">
                                         <span className="text-xs text-red-200">Tỷ lệ trễ hạn</span>
                                         <span className="text-lg font-bold text-red-400">{stats.overdueRate}%</span>
                                     </div>
                                     <div className="w-10 h-10 rounded-full border-4 border-navy-700 flex items-center justify-center text-xs font-bold" style={{ borderColor: stats.overdueRate > 0 ? '#f87171' : '#4ade80' }}>
                                         {stats.overdueRate > 0 ? '!' : 'OK'}
                                     </div>
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="bg-gradient-to-br from-purple-600 to-indigo-700 p-5 rounded-2xl shadow-lg text-white">
                        <h4 className="font-bold text-sm mb-2 opacity-90">Mẹo quản lý</h4>
                        <p className="text-xs leading-relaxed opacity-80">
                           Ưu tiên xử lý các công việc <span className="font-bold text-white">Đang làm</span> trước khi nhận việc mới để tránh dồn việc.
                        </p>
                    </div>
                </div>

                {/* 3. ANNUAL CHART (Bottom on Mobile, Left-Bottom on Desktop) */}
                <div className="lg:col-span-8 order-last lg:order-none">
                    <div className="bg-gradient-to-r from-indigo-50 to-blue-50 p-6 rounded-2xl shadow-sm border border-blue-100">
                         <div className="flex items-center justify-between mb-6">
                            <h3 className="font-bold text-navy-800 flex items-center gap-2">
                               <IconChart className="w-5 h-5 text-brand-600" />
                               Hiệu suất năm
                            </h3>
                            <span className="text-xs text-navy-600 font-medium bg-white/50 px-2 py-1 rounded border border-blue-100">Công việc hoàn thành</span>
                         </div>

                         <div className="flex items-end gap-2 h-48 w-full">
                            {chartData.map((item, index) => (
                               <div key={index} className="flex-1 flex flex-col items-center group relative">
                                  {/* Tooltip */}
                                  <div className="absolute -top-10 bg-navy-800 text-white text-[10px] py-1 px-2 rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap z-10 pointer-events-none">
                                      {item.fullLabel}: {item.count} việc
                                  </div>

                                  {/* Bar */}
                                  <div 
                                    className="w-full max-w-[30px] bg-gradient-to-t from-brand-500 to-cyan-400 rounded-t-sm hover:from-brand-600 hover:to-cyan-500 transition-all relative shadow-sm"
