                                    points={chartConfig.polylinePoints} 
                                    fill="none" 
                                    stroke="url(#lineGradient)" 
                                    strokeWidth="3"
                                    strokeLinecap="round"
                                    strokeLinejoin="round"
                                    filter="url(#glow)"
                                />
                                {/* Dots on the line */}
                                {chartData.map((item, index) => {
