                        <span className="font-bold text-4xl drop-shadow-md">{stats.overdueMonth}</span>
                     </div>
                  </div>
               </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 mt-8">

                {/* --- MONTH SUMMARY (Solid Background) --- */}
                <div className="lg:col-span-12">
