                   </button>
                 ))}
              </div>
              <button onClick={() => setReassignTask(null)} className="w-full py-3 bg-gray-100 text-gray-700 font-bold rounded-xl hover:bg-gray-200">Hủy bỏ</button>
           </div>
        </div>
      )}
