        if (startDate && taskDate < startDate) inRange = false;
        if (endDate && taskDate > endDate) inRange = false;
        return inRange;
      });
    }

    return result;
  }, [myRelevantTasks, statusFilter, completionFilter, searchQuery, startDate, endDate]);

