  );
}

const NavButton = ({ active, onClick, icon, label, badge }: any) => (
  <button onClick={onClick} className={`flex flex-col items-center gap-1 transition-all relative ${active ? 'text-navy-800 font-bold scale-105' : 'text-gray-400 hover:text-gray-600'}`}>
    <div className="relative">
       {React.cloneElement(icon, { className: 'w-6 h-6', strokeWidth: active ? 2.5 : 2 })}
       {badge && <span className="absolute -top-1 -right-2 bg-red-600 text-white text-[10px] font-bold w-4 h-4 flex items-center justify-center rounded-full animate-pulse border-2 border-white shadow-sm">{badge > 9 ? '9+' : badge}</span>}
    </div>
    <span className="text-[10px] tracking-wide">{label}</span>
  </button>
);

interface TaskCardProps {
  task: Task;
  currentUser: User;
  allUsers: User[];
  onStatusAction: (task: Task) => void;
  onReassign: (task: Task) => void;
  onEdit: (task: Task) => void;
  onViewImage: (url: string) => void;
  onViewDetail: () => void; 
  isDashboard?: boolean;
}

const TaskCard: React.FC<TaskCardProps> = ({ task, currentUser, allUsers, onStatusAction, onReassign, onEdit, onViewImage, onViewDetail, isDashboard }) => {
  const overdue = task.status !== TaskStatus.COMPLETED && isOverdue(task.dueDate);
  const dueSoon = task.status !== TaskStatus.COMPLETED && !overdue && isDueSoon(task.dueDate, 3);

  // Logic check completion overdue
  const isCompletedLate = task.status === TaskStatus.COMPLETED && task.completionImage && task.completedAt && new Date(task.completedAt) > new Date(task.dueDate);

  const isManager = currentUser.role === UserRole.MANAGER;
  const isAssignee = currentUser.id === task.assigneeId;
  const canEditStatus = isManager || isAssignee;
  const canEditContent = isManager; // Only managers can edit
  const showAction = isDashboard ? isAssignee : canEditStatus;

  const priorityColors = {
    [TaskPriority.LOW]: 'bg-gray-100 text-gray-600',
    [TaskPriority.MEDIUM]: 'bg-blue-50 text-blue-600',
    [TaskPriority.HIGH]: 'bg-orange-50 text-orange-600',
    [TaskPriority.URGENT]: 'bg-red-50 text-red-600',
  };

  const assignee = allUsers.find(u => u.id === task.assigneeId);
  const creator = allUsers.find(u => u.id === task.creatorId);
  const deadlineInfo = getDeadlineInfo(task.dueDate, task.status);

  // Card Background Color Logic
  let cardBgClass = 'bg-white border-gray-100';
  if (task.status === TaskStatus.COMPLETED) {
      cardBgClass = 'bg-green-50/50 border-green-100';
  } else if (overdue) {
      cardBgClass = 'bg-red-50 border-red-200';
  } else if (dueSoon) {
      cardBgClass = 'bg-orange-50 border-orange-200';
  }

  return (
    <div 
      className={`p-5 rounded-2xl border shadow-sm hover:shadow-md transition-shadow relative overflow-hidden group h-full flex flex-col cursor-pointer ${cardBgClass}`}
      onClick={onViewDetail} 
    >
      {overdue && <div className="absolute top-0 right-0 bg-red-600 text-white text-[10px] px-3 py-1 rounded-bl-xl font-bold z-10 shadow-sm">Quá hạn</div>}

      <div className="flex justify-between items-start mb-3">
        <span className={`text-[10px] px-2.5 py-1 rounded-md font-bold uppercase tracking-wider ${priorityColors[task.priority]}`}>{task.priority}</span>
        <div className="flex flex-col items-end gap-1">
          {deadlineInfo && <span className={`text-[10px] px-2.5 py-1 rounded-full font-bold flex items-center gap-1 ${deadlineInfo.className}`}>{deadlineInfo.icon && <IconAlert className="w-3 h-3" />}{deadlineInfo.text}</span>}
        </div>
      </div>

      <div className="flex justify-between items-start mb-2">
         <h3 className="font-bold text-gray-900 text-base leading-tight flex-1 group-hover:text-navy-800 transition-colors">{task.title}</h3>
         {canEditContent && (
             <button onClick={(e) => { e.stopPropagation(); onEdit(task); }} className="text-gray-400 hover:text-navy-600 p-1 transition-colors"><IconEdit className="w-4 h-4" /></button>
         )}
      </div>

      <p className="text-sm text-gray-600 line-clamp-3 mb-4 whitespace-pre-line flex-1">{task.description}</p>

      {/* Attachments Preview (Max 3) */}
      {task.attachments && task.attachments.length > 0 && (
         <div className="flex gap-2 overflow-x-auto pb-2 mb-3 hide-scrollbar" onClick={(e) => e.stopPropagation()}>
            {task.attachments.slice(0, 4).map((url, i) => (
               <img key={i} src={url} onClick={() => onViewImage(url)} className="w-12 h-12 rounded-lg object-cover flex-shrink-0 cursor-pointer border border-gray-200 hover:opacity-80 transition-opacity" />
            ))}
            {task.attachments.length > 4 && <div className="w-12 h-12 rounded-lg bg-gray-50 flex items-center justify-center text-xs text-gray-500 font-bold border border-gray-200">+{task.attachments.length - 4}</div>}
         </div>
      )}

      {/* Completion Proof */}
      {task.status === TaskStatus.COMPLETED && task.completionImage && (
         <div className="mb-4 bg-white/60 p-2.5 rounded-xl border border-green-200 flex items-center gap-3" onClick={(e) => e.stopPropagation()}>
             <img src={task.completionImage} onClick={() => onViewImage(task.completionImage!)} className="w-10 h-10 rounded-lg object-cover cursor-pointer hover:scale-105 transition-transform" />
             <span className="text-xs text-green-700 font-bold">Minh chứng hoàn thành</span>
         </div>
      )}

      <div className="mb-4 text-xs bg-white/50 p-3 rounded-xl text-gray-600 border border-gray-100/50">
         <div className="flex justify-between mb-1.5"><span>Ngày giao:</span><span className="font-bold text-gray-800">{formatDateTime(task.createdAt)}</span></div>
         <div className="flex justify-between"><span>Hạn chót:</span><span className={`font-bold ${overdue ? 'text-red-600' : 'text-gray-800'}`}>{formatDateTime(task.dueDate)}</span></div>
      </div>

      <div className="flex items-start justify-between mb-4 border-b border-gray-100 pb-3">
         {creator && (
            <div className="flex flex-col gap-0.5" title="Người giao việc">
                <span className="text-[10px] text-gray-400 uppercase font-bold">Người giao</span>
                <span className="text-xs text-gray-700 font-medium break-words max-w-[100px]">{creator.name}</span>
            </div>
         )}
         <div className="text-gray-300 text-xs self-center">→</div>
         {assignee && (
            <div className="flex flex-col gap-0.5 text-right items-end" title="Người thực hiện">
                <span className="text-[10px] text-gray-400 uppercase font-bold">Người nhận</span>
                <span className="text-xs text-blue-700 font-bold break-words max-w-[100px]">{assignee.name}</span>
            </div>
         )}
      </div>

      <div className="flex items-center justify-between mt-auto" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center gap-2">
           <span className={`w-2.5 h-2.5 rounded-full ${task.status === TaskStatus.COMPLETED ? 'bg-green-500' : task.status === TaskStatus.IN_PROGRESS ? 'bg-blue-500' : 'bg-gray-300'}`}></span>
           <span className={`text-xs font-bold ${task.status === TaskStatus.COMPLETED ? 'text-green-600' : task.status === TaskStatus.IN_PROGRESS ? 'text-blue-600' : 'text-gray-500'}`}>
              {task.status === TaskStatus.COMPLETED ? 'Đã xong' : task.status === TaskStatus.IN_PROGRESS ? 'Đang làm' : 'Chờ xử lý'}
           </span>
           {/* Completion Time Status Badge */}
           {task.status === TaskStatus.COMPLETED && (
               <span className={`text-[10px] px-1.5 py-0.5 rounded border font-bold ${isCompletedLate ? 'bg-red-50 text-red-600 border-red-100' : 'bg-green-50 text-green-600 border-green-100'}`}>
                   {isCompletedLate ? 'Trễ hạn' : 'Đúng hạn'}
               </span>
           )}
        </div>

        <div className="flex gap-2">
          {isManager && task.status !== TaskStatus.COMPLETED && (
             <button onClick={() => onReassign(task)} className="text-xs font-bold text-gray-500 hover:text-navy-600 bg-white hover:bg-gray-50 px-3 py-2 rounded-lg border border-gray-200 shadow-sm transition-all" title="Giao lại"><IconShare className="w-3.5 h-3.5" /></button>
          )}
          {showAction && task.status !== TaskStatus.COMPLETED && (
            <button
              onClick={() => onStatusAction(task)}
              className="text-xs font-bold bg-navy-50 hover:bg-navy-100 text-navy-800 px-4 py-2 rounded-lg border border-navy-100 transition-colors shadow-sm"
            >
              {task.status === TaskStatus.TODO ? 'Bắt đầu' : 'Hoàn thành'}
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

export enum UserRole {
  DIRECTOR = 'DIRECTOR', // Giám đốc (Người tạo công ty)
  MANAGER = 'MANAGER',   // Quản lý (Chức vụ mới)
  EMPLOYEE = 'EMPLOYEE'  // Nhân viên
}

export enum TaskStatus {
  TODO = 'TODO',
  IN_PROGRESS = 'IN_PROGRESS',
  COMPLETED = 'COMPLETED'
}

export enum TaskPriority {
  LOW = 'LOW',
  MEDIUM = 'MEDIUM',
  HIGH = 'HIGH',
  URGENT = 'URGENT'
}

export interface User {
  id: string;
  name: string;
  username: string; // Tên đăng nhập
  password?: string; // Mật khẩu (In real app, hash this!)
  companyName: string; // Tên công ty để đăng nhập
  companyId: string; // ID ẩn để link dữ liệu
  role: UserRole;
  avatar: string;
  email?: string;
}

export interface Task {
  id: string;
  companyId: string; // Link task to a specific company
  title: string;
  description: string;
  assigneeId: string;
  creatorId: string;
  dueDate: string; // ISO string
  status: TaskStatus;
  priority: TaskPriority;
  createdAt: string;
  completedAt?: string | null;
  attachments?: string[]; // Danh sách URL ảnh đính kèm khi giao việc
  completionImage?: string; // URL ảnh minh chứng khi hoàn thành
}

import React, { useState, useEffect } from 'react';
import { User, UserRole } from '../types';
import { IconBuilding, IconUser, IconLock, IconDatabase } from './Icons';
import { apiRegisterCompany, apiCheckUsernameExists, apiLogin } from '../services/storageService';
import { resetFirebaseConfig } from '../services/firebaseConfig';

interface AuthProps {
  onLogin: (user: User) => void;
  onRegisterCompany: (user: User) => void;
}

const CREDENTIALS_KEY = 'biz_saved_credentials';

const Auth: React.FC<AuthProps> = ({ onLogin, onRegisterCompany }) => {
  const [mode, setMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');

  // Form State
  const [companyName, setCompanyName] = useState('');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [fullName, setFullName] = useState(''); // Only for register
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  // Load saved credentials on mount
  useEffect(() => {
    const savedData = localStorage.getItem(CREDENTIALS_KEY);
    if (savedData) {
      try {
        const parsed = JSON.parse(savedData);
        if (parsed.companyName) setCompanyName(parsed.companyName);
        if (parsed.username) setUsername(parsed.username);
      } catch (e) {
        console.error("Error loading saved credentials", e);
      }
    }
  }, []);

  const saveCredentials = () => {
    localStorage.setItem(CREDENTIALS_KEY, JSON.stringify({
      companyName,
      username
    }));
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    if (!companyName || !username || !password || !fullName) {
      setError('Vui lòng điền đầy đủ thông tin');
      setIsLoading(false);
      return;
    }

    // 1. Check duplicate username in DB
    const exists = await apiCheckUsernameExists(companyName, username);
    if (exists) {
      setError('Tên đăng nhập đã tồn tại trong công ty này');
      setIsLoading(false);
      return;
    }

    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      name: fullName,
      username: username,
      password: password,
      companyName: companyName,
      companyId: Math.random().toString(36).substr(2, 9),
      role: UserRole.DIRECTOR, // Chức vụ cao nhất cho người tạo
      avatar: `https://ui-avatars.com/api/?name=${encodeURIComponent(fullName)}&background=random`,
      email: `${username}@${companyName.replace(/\s+/g, '').toLowerCase()}.com`
    };

    // 2. Register in DB
    const success = await apiRegisterCompany(newUser);
    if (success) {
      saveCredentials(); // Save info on success
      onRegisterCompany(newUser);
    } else {
      setError('Lỗi kết nối Server. Vui lòng thử lại sau.');
    }
    setIsLoading(false);
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    const user = await apiLogin(companyName, username, password);

    if (user) {
      saveCredentials(); // Save info on success
      onLogin(user);
    } else {
      setError('Sai tên công ty, tài khoản hoặc mật khẩu');
    }
    setIsLoading(false);
  };

  return (
    // Changed background to Navy Blue gradient
    <div className="min-h-screen bg-gradient-to-b from-navy-800 to-black flex flex-col items-center justify-center p-4">
      <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl overflow-hidden">
        {/* Header Tabs */}
        <div className="flex bg-gray-100">
          <button
            onClick={() => setMode('LOGIN')}
            className={`flex-1 py-4 font-bold text-sm transition-colors ${mode === 'LOGIN' ? 'bg-white text-navy-800 border-t-2 border-navy-800' : 'text-gray-500'}`}
          >
            Đăng Nhập
          </button>
          <button
            onClick={() => setMode('REGISTER')}
            className={`flex-1 py-4 font-bold text-sm transition-colors ${mode === 'REGISTER' ? 'bg-white text-navy-800 border-t-2 border-navy-800' : 'text-gray-500'}`}
          >
            Đăng Ký Công Ty
          </button>
        </div>

        <div className="p-8">
          <h2 className="text-2xl font-bold text-gray-800 text-center mb-6">
            {mode === 'LOGIN' ? 'Chào mừng trở lại!' : 'Khởi tạo doanh nghiệp'}
          </h2>

          <form onSubmit={mode === 'LOGIN' ? handleLogin : handleRegister} className="space-y-4">

            {/* Common: Company Name */}
            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Tên Công Ty</label>
              <div className="relative">
                <IconBuilding className="absolute left-3 top-3 w-5 h-5 text-gray-400" />
                <input
                  type="text"
                  value={companyName}
                  onChange={(e) => setCompanyName(e.target.value)}
                  placeholder="Nhập tên công ty"
                  className="w-full pl-10 pr-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-navy-800 outline-none"
                />
              </div>
            </div>

            {/* Register Only: Full Name */}
            {mode === 'REGISTER' && (
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Họ tên giám đốc</label>
                <div className="relative">
                  <IconUser className="absolute left-3 top-3 w-5 h-5 text-gray-400" />
                  <input
                    type="text"
                    value={fullName}
                    onChange={(e) => setFullName(e.target.value)}
                    placeholder="Nguyễn Văn A"
                    className="w-full pl-10 pr-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-navy-800 outline-none"
                  />
                </div>
              </div>
            )}

            {/* Common: Username */}
            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Tên đăng nhập</label>
              <div className="relative">
                <IconUser className="absolute left-3 top-3 w-5 h-5 text-gray-400" />
                <input
                  type="text"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  placeholder="admin"
                  className="w-full pl-10 pr-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-navy-800 outline-none"
                />
              </div>
            </div>

            {/* Common: Password */}
            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Mật khẩu</label>
              <div className="relative">
                <IconLock className="absolute left-3 top-3 w-5 h-5 text-gray-400" />
                <input
                  type="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="••••••••"
                  className="w-full pl-10 pr-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-navy-800 outline-none"
                />
              </div>
            </div>

            {error && (
              <div className="bg-red-50 text-red-600 text-sm p-3 rounded-lg text-center">
                {error}
              </div>
            )}

            <button
              type="submit"
              disabled={isLoading}
              className="w-full bg-navy-800 text-white font-bold py-3 rounded-xl hover:bg-navy-900 transition shadow-lg mt-4 flex items-center justify-center disabled:opacity-70 disabled:cursor-not-allowed"
            >
              {isLoading ? (
                <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
              ) : (
                mode === 'LOGIN' ? 'Đăng Nhập' : 'Tạo Công Ty'
              )}
            </button>
          </form>

          {/* Reset Config Link */}
          <div className="mt-6 text-center">
            <button 
              onClick={() => {
                if(window.confirm('Bạn có chắc muốn xóa cấu hình Server để nhập mới?')) {
                  resetFirebaseConfig();
                }
              }}
              className="text-xs text-gray-400 hover:text-gray-600 flex items-center justify-center gap-1 w-full"
            >
              <IconDatabase className="w-3 h-3" />
              Cài đặt lại kết nối Server
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Auth;

import React, { useState, useRef, useEffect } from 'react';
import { User, UserRole, TaskPriority, Task } from '../types';
import { analyzeTaskAudio } from '../services/geminiService';
import { uploadTaskImage } from '../services/storageService';
import { IconMic, IconX, IconImage, IconAlert } from './Icons';

interface CreateTaskModalProps {
  currentUser: User;
  assignableUsers: User[]; 
  onClose: () => void;
  onCreate: (taskData: any) => Promise<void>;
  onEdit?: (taskData: any) => Promise<void>;
  initialData?: Task;
}

const CreateTaskModal: React.FC<CreateTaskModalProps> = ({ currentUser, assignableUsers, onClose, onCreate, onEdit, initialData }) => {
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [dueDate, setDueDate] = useState('');
  const [assigneeId, setAssigneeId] = useState(currentUser.id);
  const [priority, setPriority] = useState<TaskPriority>(TaskPriority.MEDIUM);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [isUploading, setIsUploading] = useState(false);

  // Image State
  const [selectedFiles, setSelectedFiles] = useState<File[]>([]);
  const [existingImages, setExistingImages] = useState<string[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Audio Recording Refs
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  // Director và Manager đều có quyền giao việc
  const canAssign = currentUser.role === UserRole.DIRECTOR || currentUser.role === UserRole.MANAGER;

  // Load initial data if editing
  useEffect(() => {
    if (initialData) {
      setTitle(initialData.title);
      setDescription(initialData.description);
      // Format date for input datetime-local: YYYY-MM-DDTHH:mm
      try {
        const d = new Date(initialData.dueDate);
        // Adjust to local ISO string manually to handle timezone correctly for inputs
        if (!isNaN(d.getTime())) {
            const localIso = new Date(d.getTime() - (d.getTimezoneOffset() * 60000)).toISOString().slice(0, 16);
            setDueDate(localIso);
        } else {
            setDueDate('');
        }
      } catch (e) {
        setDueDate('');
      }

      setAssigneeId(initialData.assigneeId);
      setPriority(initialData.priority);
      if (initialData.attachments) {
        setExistingImages(initialData.attachments);
      }
    }
  }, [initialData]);

  // Voice Command Logic
  const handleVoiceCommand = async () => {
    if (isRecording) {
      if (mediaRecorderRef.current && mediaRecorderRef.current.state === "recording") {
        mediaRecorderRef.current.stop();
        setIsRecording(false);
        setIsAnalyzing(true);
      }
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

        // iOS Safari does NOT support audio/webm. We must check supported types.
        let mimeType = 'audio/webm';
        if (MediaRecorder.isTypeSupported('audio/webm')) {
            mimeType = 'audio/webm';
        } else if (MediaRecorder.isTypeSupported('audio/mp4')) {
            mimeType = 'audio/mp4'; // iOS fallback
        } else {
            console.warn("No suitable audio mime type found, letting browser decide.");
            mimeType = ''; // Let browser use default
        }

        const options = mimeType ? { mimeType } : undefined;
        const mediaRecorder = new MediaRecorder(stream, options);

        mediaRecorderRef.current = mediaRecorder;
        audioChunksRef.current = [];

        mediaRecorder.ondataavailable = (event: BlobEvent) => {
          if (event.data.size > 0) {
            audioChunksRef.current.push(event.data);
          }
        };

        mediaRecorder.onstop = async () => {
          // Use the correct mime type for the blob
          const finalMimeType = mimeType || 'audio/mp4';
          const audioBlob = new Blob(audioChunksRef.current, { type: finalMimeType });

          const reader = new FileReader();
          reader.readAsDataURL(audioBlob);
          reader.onloadend = async () => {
            const base64String = reader.result as string;
            // Handle both data:audio/webm;base64,... and data:audio/mp4;base64,...
            const base64Data = base64String.split(',')[1];

            const transcription = await analyzeTaskAudio(base64Data, finalMimeType);

            if (transcription) {
              if (!title) {
                setTitle(transcription);
              } else {
                setDescription(prev => (prev ? prev + '\n' + transcription : transcription));
              }
            }
            setIsAnalyzing(false);
            stream.getTracks().forEach(track => track.stop());
          };
        };

        mediaRecorder.start();
        setIsRecording(true);
      } catch (err) {
        console.error("Error accessing microphone:", err);
        alert("Không thể truy cập Microphone. Trên iOS, vui lòng kiểm tra Cài đặt > Safari > Microphone.");
        setIsRecording(false);
      }
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const filesArray: File[] = Array.from(e.target.files);
      // REMOVED 5MB Check to allow larger files to be compressed
      setSelectedFiles(prev => [...prev, ...filesArray]);
    }
  };

  const removeSelectedFile = (index: number) => {
    setSelectedFiles(prev => prev.filter((_, i) => i !== index));
  };

  const removeExistingImage = (url: string) => {
    setExistingImages(prev => prev.filter(img => img !== url));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title || !dueDate) {
       alert("Vui lòng nhập tiêu đề và hạn chót!");
       return;
    }

    setIsUploading(true);

    try {
      const tempTaskId = initialData?.id || Math.random().toString(36).substr(2, 9);

      // Upload images
      const uploadPromises = selectedFiles.map(file => uploadTaskImage(file, tempTaskId));
      const results = await Promise.all(uploadPromises);

      // Filter successful uploads
      const validNewUrls = results.filter(url => url !== null) as string[];

      // Error handling for uploads
      if (selectedFiles.length > 0 && validNewUrls.length === 0) {
         const continueSave = window.confirm("Không thể tải ảnh lên (Lỗi kết nối hoặc quyền truy cập). Bạn có muốn tiếp tục lưu công việc mà không có ảnh mới?");
         if (!continueSave) {
           setIsUploading(false);
           return;
         }
      } else if (selectedFiles.length > validNewUrls.length) {
         alert(`Cảnh báo: Chỉ tải lên được ${validNewUrls.length}/${selectedFiles.length} ảnh.`);
      }

      const allAttachments = [...existingImages, ...validNewUrls];

      const data = {
        id: tempTaskId, 
        title,
        description,
        dueDate: new Date(dueDate).toISOString(),
        assigneeId: canAssign ? assigneeId : currentUser.id,
        priority,
        attachments: allAttachments
      };

      if (initialData && onEdit) {
        await onEdit({ ...initialData, ...data });
      } else {
        await onCreate(data);
      }
      onClose(); // Close strictly after success
    } catch (error) {
      console.error("Error saving task:", error);
      alert("Có lỗi xảy ra khi lưu công việc. Vui lòng thử lại.");
    } finally {
      setIsUploading(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/50 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 backdrop-blur-sm animate-fade-in">
      <div className="bg-white w-full sm:max-w-lg rounded-t-2xl sm:rounded-2xl p-6 shadow-2xl animate-slide-up sm:animate-none max-h-[90vh] overflow-y-auto custom-scrollbar flex flex-col">
        <div className="flex justify-between items-center mb-6 border-b border-gray-100 pb-4">
          <h2 className="text-xl font-bold text-navy-800">
            {initialData ? 'Sửa Công Việc' : 'Giao Việc Mới'}
          </h2>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600 p-2 rounded-full hover:bg-gray-100"><IconX className="w-5 h-5"/></button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-5">

          {/* Title Input */}
          <div>
            <label className="block text-sm font-bold text-gray-700 mb-1">Nhiệm vụ <span className="text-red-500">*</span></label>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="VD: Báo cáo thu chi tháng 12..."
              className="w-full p-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-navy-800 outline-none transition-all font-medium"
              required={!isRecording}
              disabled={isUploading}
            />
          </div>

          {/* Description Input with Voice */}
          <div>
            <label className="block text-sm font-bold text-gray-700 mb-1">Mô tả chi tiết</label>
            <div className="relative">
               <textarea
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                rows={4}
                className="w-full p-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-navy-800 outline-none resize-none transition-all text-sm"
                placeholder="Chi tiết công việc..."
                disabled={isUploading}
              />
              <button
                type="button"
                onClick={handleVoiceCommand}
                disabled={isAnalyzing || isUploading}
                className={`absolute bottom-3 right-3 p-2 rounded-full shadow-sm transition-all ${
                  isRecording ? 'bg-red-500 text-white animate-pulse' : 
                  isAnalyzing ? 'bg-yellow-400 text-white' : 'bg-gray-100 text-gray-500 hover:bg-gray-200'
                }`}
                title="Nhập bằng giọng nói (AI)"
              >
                <IconMic className="w-4 h-4" />
              </button>
            </div>
            {isAnalyzing && <p className="text-xs text-yellow-600 mt-1 font-medium italic">Đang phân tích giọng nói...</p>}
          </div>

          {/* Image Upload Area */}
          <div>
             <label className="block text-sm font-bold text-gray-700 mb-2">Hình ảnh đính kèm</label>

             {/* Preview Grid */}
             <div className="grid grid-cols-4 gap-2 mb-3">
                {existingImages.map((url, idx) => (
                   <div key={`exist-${idx}`} className="relative group aspect-square rounded-lg overflow-hidden border border-gray-200">
                      <img src={url} className="w-full h-full object-cover" />
                      <button type="button" onClick={() => removeExistingImage(url)} className="absolute top-0.5 right-0.5 bg-red-500 text-white rounded-full p-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
                        <IconX className="w-3 h-3"/>
                      </button>
                   </div>
                ))}
                {selectedFiles.map((file, idx) => (
                   <div key={`new-${idx}`} className="relative group aspect-square rounded-lg overflow-hidden border border-gray-200">
                      <img src={URL.createObjectURL(file)} className="w-full h-full object-cover" />
                      <div className="absolute inset-0 bg-green-500/10 pointer-events-none"></div> {/* Indicator for new files */}
                      <button type="button" onClick={() => removeSelectedFile(idx)} className="absolute top-0.5 right-0.5 bg-red-500 text-white rounded-full p-0.5">
                        <IconX className="w-3 h-3"/>
                      </button>
                   </div>
                ))}

                {/* Add Button */}
                <button 
                  type="button" 
                  onClick={() => fileInputRef.current?.click()}
                  className="aspect-square rounded-lg border-2 border-dashed border-gray-300 flex flex-col items-center justify-center text-gray-400 hover:border-navy-500 hover:text-navy-500 hover:bg-gray-50 transition-all"
                  disabled={isUploading}
                >
                   <IconImage className="w-6 h-6 mb-1"/>
                </button>
             </div>
             <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleFileSelect} 
                className="hidden" 
                multiple 
                accept="image/*" 
             />
          </div>

          {/* Row: Due Date & Priority */}
          <div className="grid grid-cols-2 gap-4">
             <div>
                <label className="block text-sm font-bold text-gray-700 mb-1">Hạn chót <span className="text-red-500">*</span></label>
                <input
                  type="datetime-local"
                  value={dueDate}
                  onChange={(e) => setDueDate(e.target.value)}
                  className="w-full p-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-navy-800 outline-none text-sm font-medium"
                  required
                  disabled={isUploading}
                />
             </div>
             <div>
                <label className="block text-sm font-bold text-gray-700 mb-1">Độ ưu tiên</label>
                <select
                  value={priority}
                  onChange={(e) => setPriority(e.target.value as TaskPriority)}
                  className="w-full p-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-navy-800 outline-none text-sm bg-white"
                  disabled={isUploading}
                >
                  <option value={TaskPriority.LOW}>Thấp</option>
                  <option value={TaskPriority.MEDIUM}>Trung bình</option>
                  <option value={TaskPriority.HIGH}>Cao</option>
                  <option value={TaskPriority.URGENT}>Khẩn cấp</option>
                </select>
             </div>
          </div>

          {/* Assignee (Director/Manager Only) */}
          {canAssign && (
            <div>
              <label className="block text-sm font-bold text-gray-700 mb-1">Giao cho nhân viên</label>
              <select
                value={assigneeId}
                onChange={(e) => setAssigneeId(e.target.value)}
                className="w-full p-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-navy-800 outline-none text-sm bg-white"
                disabled={isUploading}
              >
                {assignableUsers.map(user => (
                  <option key={user.id} value={user.id}>
                    {user.name} ({user.username})
                  </option>
                ))}
              </select>
            </div>
          )}

          {/* Submit Button */}
          <button
            type="submit"
            disabled={isUploading}
            className={`w-full py-4 rounded-xl font-bold text-white shadow-lg transition-all flex items-center justify-center gap-2 mt-4 ${
               isUploading ? 'bg-gray-400 cursor-not-allowed' : 'bg-navy-800 hover:bg-navy-900 active:scale-[0.98]'
            }`}
          >
            {isUploading ? (
               <>
                 <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                 <span>Đang tải ảnh lên...</span>
               </>
            ) : (
               initialData ? 'Lưu thay đổi' : 'Giao việc ngay'
            )}
          </button>
        </form>
      </div>
    </div>
  );
};

