      const points = chartData.map((item, index) => {
          const x = ((index + 0.5) / chartData.length) * 100; // Center of the bar
          const y = 100 - (item.count / maxVal) * 100;
          return `${x},${y}`;
      });

      const polylinePoints = points.join(' ');

      return { maxVal, polylinePoints };
  }, [chartData]);


